def load_words() -> list[dict]:
    data = json.loads((EDIT / "transcripts" / "webcam.json").read_text(encoding="utf-8"))
    ws = [w for w in data["words"] if w["type"] == "word"]
    for w in ws:
        w["real_end"] = min(w["end"], w["start"] + REAL_MAX_WORD)
    return ws


def autopad(idx: int, start: float, end: float, ws: list[dict]) -> tuple[float, float, list[str]]:
    """Push an OUT point past the end of the last word it contains, and an IN
    point back before the start of the first word it contains, so no cut
    lands inside speech. Only ever moves outward, never inward -- so a
    hand-chosen boundary that already has room is left exactly as written."""
    notes: list[str] = []

    if (idx, "OUT") not in NO_AUTOPAD:
        inside = [w for w in ws if w["start"] < end < w["real_end"]]
        if inside:
            w = inside[-1]
            nxt = next((n for n in ws if n["start"] >= w["real_end"]), None)
            target = w["real_end"] + PAD_OUT
            if nxt is not None:
                target = min(target, nxt["start"] - GUARD)
            if target > end:
                notes.append(f"OUT {end:.2f}->{target:.2f} (clears '{w['text']}')")
                end = round(target, 3)

    if (idx, "IN") not in NO_AUTOPAD:
        inside = [w for w in ws if w["start"] < start < w["real_end"]]
        if inside:
            w = inside[0]
            prv = next((p for p in reversed(ws) if p["real_end"] <= w["start"]), None)
            target = w["start"] - PAD_IN
            if prv is not None:
                target = max(target, prv["real_end"] + GUARD)
            if target < start:
                notes.append(f"IN  {start:.2f}->{target:.2f} (clears '{w['text']}')")
                start = round(target, 3)

    return start, end, notes


