"""Generate this episode's one-off motion-graphic slots.

Six cards share one liquid-glass shell (see tools/video-use/LIQUID_GLASS_STYLE.md
for the tokens), so the shell lives here once instead of being copy-pasted into
six near-identical HTML files. Each card supplies only its own body markup and
its own GSAP timeline.

PLACEMENT CONTRACT -- read before changing any `left`/`top`/`width`:

  Hero-stage cards (composited over the retrowave background while the webcam
  is in its shrink-aside state) must keep ALL rendered content inside
  x 60..950, y 80..1000. The aside webcam box is 850x638 centred at
  (1455, 540) -> x 1030..1880, so that leaves a real >=80px gap rather than
  "technically not touching". Verify with scripts/bbox.py after rendering --
  CSS geometry does not account for glow, blur or shadow spread, and the
  union box across the card's FULL duration is what matters, not frame 1.

  Screen-recording cards sit over a PIP that lives BOTTOM-LEFT for this
  episode (x 40..616, y 608..1040 plus ~27px of neon-border glow), so they
  anchor to the top band instead.

Timings below are all relative to each card's own t=0; where that t=0 lands in
the episode is set by OVERLAYS in composite_full.py.
"""
from __future__ import annotations

import json
import shutil
import sys
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

EDIT = Path(__file__).resolve().parent.parent
ANIM = EDIT / "animations"
TEMPLATE_SRC = ANIM / "slot_tag_bug"  # donor for hyperframes.json / package.json / AGENTS.md

SHELL = """<!doctype html>
<html lang="en" data-resolution="landscape">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=1920, height=1080" />
    <title>{title}</title>
    <script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      href="https://fonts.googleapis.com/css2?family=Geist:wght@400;600;700;800;900&display=swap"
      rel="stylesheet"
    />
    <style>
      * {{ margin: 0; padding: 0; box-sizing: border-box; }}

      /* Alpha overlay -- never paint an opaque background. */
      html, body {{
        width: 1920px; height: 1080px; overflow: hidden; background: transparent;
      }}
      body {{ font-family: "Geist", "Inter", sans-serif; }}

      #root {{
        position: relative; width: 1920px; height: 1080px;
        overflow: hidden; background: transparent;
      }}
      #scene {{ position: absolute; inset: 0; }}

      /* ---------- brand glow behind the card ---------- */
      .glow-pos {{ position: absolute; left: {glow_cx}px; top: {glow_cy}px; transform: translate(-50%, -50%); }}
      #glow {{
        width: {glow_w}px; height: {glow_h}px; border-radius: 50%;
        background: radial-gradient(ellipse at center,
          rgba(255, 130, 170, 0.42) 0%,
          rgba(255, 150, 120, 0.28) 40%,
          rgba(210, 70, 190, 0.16) 64%,
          rgba(210, 70, 190, 0) 78%);
        filter: blur(44px);
        opacity: 0;
      }}

      /* ---------- liquid-glass card ---------- */
      .card-pos {{ position: absolute; left: {card_x}px; top: {card_y}px; }}
      #card {{
        position: relative;
        width: {card_w}px;
        padding: {card_pad};
        border-radius: 34px;
        opacity: 0;
        background: linear-gradient(150deg,
          rgba(255, 255, 255, 0.20) 0%,
          rgba(255, 255, 255, 0.08) 48%,
          rgba(255, 255, 255, 0.13) 100%);
        -webkit-backdrop-filter: blur(26px) saturate(170%);
        backdrop-filter: blur(26px) saturate(170%);
        border: 1.5px solid rgba(255, 255, 255, 0.42);
        box-shadow:
          0 28px 64px rgba(18, 8, 24, 0.42),
          0 2px 0 rgba(255, 255, 255, 0.32) inset,
          0 -16px 28px rgba(120, 40, 90, 0.10) inset;
        overflow: hidden;
      }}
      /* top light-catch: the cue that reads as glass rather than flat card */
      #card::before {{
        content: ""; position: absolute; inset: 0; pointer-events: none;
        background: linear-gradient(180deg, rgba(255,255,255,0.38) 0%, rgba(255,255,255,0) 30%);
      }}

      .eyebrow {{
        position: relative;
        font-size: 22px; font-weight: 700; letter-spacing: 5px; text-transform: uppercase;
        color: rgba(255, 255, 255, 0.62);
        opacity: 0;
      }}
      .eyebrow .dot {{
        display: inline-block; width: 9px; height: 9px; border-radius: 50%;
        margin-right: 13px; vertical-align: middle;
        background: linear-gradient(120deg, #ff7aa8, #cf3fc4);
        box-shadow: 0 0 14px 2px rgba(207, 63, 196, 0.6);
      }}

      .grad {{
