def main() -> None:
    for name, c in CARDS.items():
        d = ANIM / name
        d.mkdir(parents=True, exist_ok=True)
        for f in ("hyperframes.json", "AGENTS.md", "CLAUDE.md"):
            src = TEMPLATE_SRC / f
            if src.exists():
                shutil.copy(src, d / f)
        pkg = json.loads((TEMPLATE_SRC / "package.json").read_text(encoding="utf-8"))
        pkg["name"] = name
        (d / "package.json").write_text(json.dumps(pkg, indent=2) + "\n", encoding="utf-8")
        (d / "meta.json").write_text(json.dumps({"id": name, "name": name}, indent=2) + "\n",
                                     encoding="utf-8")
        (d / "index.html").write_text(SHELL.format(**c), encoding="utf-8")
        print(f"  {name:<22} dur={c['dur']:>5.2f}s  card x {c['card_x']}..{c['card_x'] + c['card_w']}")
    print(f"\n{len(CARDS)} slots written to {ANIM}")


if __name__ == "__main__":
    main()

