        text-shadow: 0 2px 12px rgba(0, 0, 0, 0.45);
        white-space: normal;
      }
    </style>
  </head>
  <body>
    <div
      id="root"
      data-composition-id="main"
      data-start="0"
      data-duration="539.36"
      data-width="1920"
      data-height="1080"
      data-fps="60"
    >
      <div
        id="caption-track"
        class="clip"
        data-start="0"
        data-duration="539.36"
        data-track-index="1"
      >
        <div id="stage" aria-hidden="true"></div>
      </div>
    </div>

    <script src="cues.js"></script>
    <script>
      (function () {
        var stage = document.getElementById("stage");
        var frag = document.createDocumentFragment();

        // Build DOM: one lightweight .cap-item per cue (588 total), each just
        // a pill + text span. Only one is ever opacity:1 at a time; the
        // framework never sees per-cue timing (no class="clip" on these), so
        // there is no 588-element clip-lint or clip-lifecycle cost — visibility
        // is purely a function of our own timeline below.
        CUES.forEach(function (cue, i) {
          var item = document.createElement("div");
          item.className = "cap-item";
          item.id = "cap-item-" + i;
          var pill = document.createElement("div");
          pill.className = "cap-pill";
          var text = document.createElement("span");
          text.className = "cap-text";
          text.textContent = cue.t;
          pill.appendChild(text);
          item.appendChild(pill);
          frag.appendChild(item);
        });
        stage.appendChild(frag);

        window.__timelines = window.__timelines || {};
        var tl = gsap.timeline({ paused: true });

        // Data-driven track: generated from a JS loop over CUES (baked from
