"""Build the full-video caption overlay composition from caption_cues.json.

Two deliberate departures from the previous episode's caption slot:

* CANVAS IS 1920x320, NOT 1920x1080. The overlay is a pill in the bottom
  band; the other 70% of every frame is empty alpha that still costs full
  render time. At ~16x realtime, a 12.5-minute full-frame alpha render is
  3-4 hours of compute for nothing. The strip is composited back at y=760,
  which puts the pill's bottom edge at y=988 -- identical to before.

* PILL FILL IS DARK, NOT A WHITE WASH. LIQUID_GLASS_STYLE.md calls for a
  darker tinted fill (~rgba(20-36,10-15,18-30, 0.64-0.72)) on captions
  specifically, because unlike a card authored against a known background
  they sit over constantly-changing content -- and half this episode is a
  white browser page. The previous episode's slot still had the light
  ~0.2/0.07 white wash, which vanishes over the Kodely homepage.

Pill max-width is 620px so the centred pill clears the webcam PIP in BOTH
corner positions (see composite_full.PIP_W for that arithmetic).

Set CAPTION_PROBE_S to build a short probe composition instead of the full
one, to sanity-check geometry before committing to the long render.
"""
from __future__ import annotations

import json
import os
import shutil
import sys
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

EDIT = Path(__file__).resolve().parent.parent
ANIM = EDIT / "animations"
DONOR = ANIM / "slot_tag_bug"

CANVAS_W, CANVAS_H = 1920, 320
PILL_BOTTOM = 92          # from the bottom of the STRIP == from the bottom of the frame
OVERLAY_Y = 1080 - CANVAS_H  # 760 -- where composite_full places the strip
MAX_WIDTH = 620

HTML = """<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width={W}, height={H}" />
    <title>Captions - Full Video Overlay</title>
    <script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      href="https://fonts.googleapis.com/css2?family=Geist:wght@400;600;700;800;900&display=swap"
      rel="stylesheet"
    />
    <style>
      * {{ margin: 0; padding: 0; box-sizing: border-box; }}
      html, body {{
        width: {W}px; height: {H}px; overflow: hidden; background: transparent;
      }}
      body {{ font-family: "Geist", "Inter", sans-serif; }}

      #root {{ position: relative; width: {W}px; height: {H}px; background: transparent; }}
      #caption-track {{ position: absolute; inset: 0; }}

      #stage {{
        position: absolute; left: 0; right: 0; bottom: {PB}px; height: 140px;
        display: flex; align-items: flex-end; justify-content: center;
        pointer-events: none;
      }}

      .cap-item {{
        position: absolute; left: 50%; bottom: 0;
        transform: translateX(-50%); transform-origin: 50% 100%;
        opacity: 0; display: flex; justify-content: center;
        max-width: {MW}px;
      }}

      /* Darker tinted fill, not the light white wash -- captions have to stay
         legible over a bright white browser page as well as over the dark
         retrowave stage. */
      .cap-pill {{
        position: relative; display: inline-flex; align-items: center;
        justify-content: center; padding: 15px 34px; border-radius: 22px;
        background: linear-gradient(135deg,
          rgba(32, 14, 26, 0.72) 0%,
          rgba(22, 10, 20, 0.64) 100%);
        -webkit-backdrop-filter: blur(22px) saturate(150%);
        backdrop-filter: blur(22px) saturate(150%);
        box-shadow:
          0 14px 40px rgba(0, 0, 0, 0.45),
          inset 0 1px 0 rgba(255, 255, 255, 0.30),
          inset 0 -1px 0 rgba(255, 255, 255, 0.05);
        overflow: hidden;
      }}
      .cap-pill::before {{
        content: ""; position: absolute; inset: 0; border-radius: inherit;
        padding: 1.5px; pointer-events: none;
        background: linear-gradient(135deg,
          rgba(255, 255, 255, 0.62) 0%,
          rgba(255, 255, 255, 0.10) 30%,
          rgba(255, 255, 255, 0) 55%,
          rgba(255, 255, 255, 0.22) 100%);
        -webkit-mask:
          linear-gradient(#fff 0 0) content-box,
          linear-gradient(#fff 0 0);
        -webkit-mask-composite: xor;
        mask-composite: exclude;
      }}

      .cap-text {{
        position: relative; z-index: 1;
        font-size: 36px; font-weight: 800; letter-spacing: 0.1px;
        line-height: 1.28; color: #ffffff; text-align: center;
        text-shadow: 0 2px 12px rgba(0, 0, 0, 0.55);
        white-space: normal;
      }}
    </style>
  </head>
  <body>
    <div id="root" data-composition-id="main" data-start="0" data-duration="{DUR}"
         data-width="{W}" data-height="{H}" data-fps="60">
      <div id="caption-track" class="clip" data-start="0" data-duration="{DUR}"
           data-track-index="1">
        <div id="stage" aria-hidden="true"></div>
      </div>
    </div>

    <script src="cues.js"></script>
    <script>
      (function () {{
        var stage = document.getElementById("stage");
        var frag = document.createDocumentFragment();
        CUES.forEach(function (cue, i) {{
          var item = document.createElement("div");
          item.className = "cap-item";
          item.id = "cap-item-" + i;
          var pill = document.createElement("div");
          pill.className = "cap-pill";
          var text = document.createElement("span");
          text.className = "cap-text";
          text.textContent = cue.t;
          pill.appendChild(text);
          item.appendChild(pill);
          frag.appendChild(item);
        }});
        stage.appendChild(frag);

        window.__timelines = window.__timelines || {{}};
        var tl = gsap.timeline({{ paused: true }});

        // Data-driven, and every visibility change is a tl.set()/tl.fromTo()
        // at an explicit time -- seek-safe, because the renderer samples by
        // tl.seek(t) rather than playing through.
        CUES.forEach(function (cue, i) {{
          var sel = "#cap-item-" + i;
          var dur = cue.e - cue.s;
          var popDur = Math.min(0.08, Math.max(0.035, dur * 0.35));
          tl.fromTo(sel, {{ opacity: 0, scale: 0.92 }},
            {{ opacity: 1, scale: 1, duration: popDur, ease: "back.out(2.4)" }}, cue.s);
          tl.set(sel, {{ opacity: 0 }}, cue.e);
        }});

        tl.to({{}}, {{ duration: CUES_DURATION }}, 0);
        window.__timelines["main"] = tl;
      }})();
    </script>
  </body>
</html>
"""


def main() -> None:
    probe = float(os.environ.get("CAPTION_PROBE_S", "0"))
    name = "slot_captions_probe" if probe else "slot_captions"
    d = ANIM / name
    d.mkdir(parents=True, exist_ok=True)
    for f in ("hyperframes.json", "AGENTS.md", "CLAUDE.md"):
        if (DONOR / f).exists():
            shutil.copy(DONOR / f, d / f)
    pkg = json.loads((DONOR / "package.json").read_text(encoding="utf-8"))
    pkg["name"] = name
    (d / "package.json").write_text(json.dumps(pkg, indent=2) + "\n", encoding="utf-8")
    (d / "meta.json").write_text(json.dumps({"id": name, "name": name}, indent=2) + "\n",
                                 encoding="utf-8")

    raw = json.loads((EDIT / "caption_cues.json").read_text(encoding="utf-8"))
    cues = sorted(({"s": float(c["start"]), "e": float(c["end"]), "t": c["text"]}
                   for c in raw), key=lambda c: c["s"])
    if probe:
        cues = [c for c in cues if c["e"] <= probe]
    # Clip each cue against the next so two pills never render at once.
    for i, c in enumerate(cues[:-1]):
        if cues[i + 1]["s"] < c["e"]:
            c["e"] = cues[i + 1]["s"]
        if c["e"] <= c["s"]:
            c["e"] = c["s"] + 0.05
    for c in cues:
        c["s"], c["e"] = round(c["s"], 3), round(c["e"], 3)

    dur = round(cues[-1]["e"] + 1.0, 2)
    (d / "cues.js").write_text(
        f"// AUTO-GENERATED by make_captions_slot.py -- do not hand-edit.\n"
        f"// {len(cues)} cues, last ends {cues[-1]['e']}s.\n"
        f"var CUES = {json.dumps(cues)};\nvar CUES_DURATION = {dur};\n",
        encoding="utf-8")
    (d / "index.html").write_text(
        HTML.format(W=CANVAS_W, H=CANVAS_H, PB=PILL_BOTTOM, MW=MAX_WIDTH, DUR=dur),
        encoding="utf-8")

    print(f"{name}: {len(cues)} cues, duration {dur}s, canvas {CANVAS_W}x{CANVAS_H}")
    print(f"  composite at y={OVERLAY_Y} -> pill bottom lands at y={OVERLAY_Y + CANVAS_H - PILL_BOTTOM}")


if __name__ == "__main__":
    main()

