"""Output start time of each segment computed from REAL encoded clip
durations (ffprobe), not the EDL's nominal ones -- the two differ by a few ms
per segment, which compounds to ~0.36s over 60 segments."""
import json, subprocess, sys
from pathlib import Path
E = Path(r"C:\Users\edmem\OneDrive\Desktop\Video Projects\vibe-coding-ep1-kodely\edit")
R = json.loads((E/"edl.json").read_text(encoding="utf-8"))["ranges"]
XF = 0.4
def dur(p):
    r = subprocess.run(["ffprobe","-v","error","-select_streams","v:0",
        "-show_entries","stream=duration","-of","csv=p=0",str(p)],capture_output=True,text=True)
    return float(r.stdout.strip())
# rebuild the chain structure exactly as composite_full does
bounds_nom=[]; cum=0.0; prev=None
for r in R:
    if prev is not None and r["layout"]!=prev: cum-=XF
    bounds_nom.append(cum); cum+=r["end"]-r["start"]; prev=r["layout"]
chains=[]; bnds=[]
for i in range(1,len(R)):
    if R[i]["layout"]!=R[i-1]["layout"]: bnds.append((i-1,i))
for a,b in bnds:
    if chains and chains[-1][-1]==a: chains[-1].append(b)
    else: chains.append([a,b])
in_chain={}
for ch in chains:
    for n,s in enumerate(ch): in_chain[s]=(ch,n)
# walk the final concat order
real={}; cum=0.0; i=0
while i < len(R):
    if i in in_chain and in_chain[i][1]==0:
        ch,_=in_chain[i]
        tag="_".join(f"{c:02d}" for c in ch)
        merged=E/"clips_transitions"/f"trans_{tag}.mp4"
        # inside the merged clip, member n starts at sum(real dur of prior members) - n*XF
        off=0.0
        for n,s in enumerate(ch):
            real[s]=cum+off
            off += dur(E/"clips_composited"/f"seg_{s:02d}.mp4") - XF
        cum += dur(merged)
        i = ch[-1]+1
    else:
        real[i]=cum
        cum += dur(E/"clips_composited"/f"seg_{i:02d}.mp4")
        i += 1
print(f"{'seg':>3} {'nominal':>9} {'real':>9} {'diff(ms)':>9}")
