"""Captions + final pass for a vertical Short.

Same principles as the 16:9 build, re-tuned for a 1080-wide frame:
  * shorter chunks (4-5 words, not 6) and bigger type (50px, not 36) --
    a phone-width pill cannot hold a 6-word line at readable size
  * cue times come from the PROBED durations of the clips that were actually
    concatenated, never from nominal range arithmetic (see the 16:9 build's
    2-second caption drift for why)
  * loudness normalised once at the end, video and audio processed
    separately then muxed, with the same decoded-sample-count gate
"""
from __future__ import annotations

import json
import re
import shutil
import subprocess
import sys
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8", errors="replace")
sys.path.insert(0, str(Path(__file__).resolve().parent))
from shorts import SHORTS, OUT_DIR, H, W  # noqa: E402

EDIT = Path(__file__).resolve().parent.parent
ANIM = EDIT / "animations"
DONOR = ANIM / "slot_tag_bug"

STRIP_H = 320
STRIP_Y = H - STRIP_H          # 1600
PILL_BOTTOM = 80               # -> pill bottom edge lands at y=1840
MAX_WIDTH = 900
FONT_PX = 50
MAX_CHUNK = 5
GAP_BREAK = 0.45
TARGET_I, TARGET_TP, TARGET_LRA = -14.0, -1.5, 11.0

HTML = """<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <title>Short captions</title>
    <script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Geist:wght@400;700;800;900&display=swap" rel="stylesheet" />
    <style>
      * {{ margin:0; padding:0; box-sizing:border-box; }}
      html, body {{ width:{W}px; height:{SH}px; overflow:hidden; background:transparent; }}
      body {{ font-family:"Geist","Inter",sans-serif; }}
      #root {{ position:relative; width:{W}px; height:{SH}px; background:transparent; }}
      #track {{ position:absolute; inset:0; }}
      #stage {{ position:absolute; left:0; right:0; bottom:{PB}px; height:200px;
                display:flex; align-items:flex-end; justify-content:center; }}
      .cap-item {{ position:absolute; left:50%; bottom:0; transform:translateX(-50%);
                   transform-origin:50% 100%; opacity:0; display:flex;
                   justify-content:center; max-width:{MW}px; }}
      .cap-pill {{ position:relative; display:inline-flex; align-items:center;
                   justify-content:center; padding:18px 38px; border-radius:26px;
                   background:linear-gradient(135deg, rgba(32,14,26,0.78) 0%, rgba(22,10,20,0.70) 100%);
                   -webkit-backdrop-filter:blur(22px) saturate(150%);
                   backdrop-filter:blur(22px) saturate(150%);
                   box-shadow:0 16px 44px rgba(0,0,0,0.5),
                              inset 0 1px 0 rgba(255,255,255,0.30); overflow:hidden; }}
      .cap-pill::before {{ content:""; position:absolute; inset:0; border-radius:inherit;
        padding:1.5px; pointer-events:none;
        background:linear-gradient(135deg, rgba(255,255,255,0.62) 0%,
          rgba(255,255,255,0.10) 30%, rgba(255,255,255,0) 55%, rgba(255,255,255,0.22) 100%);
        -webkit-mask:linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
        -webkit-mask-composite:xor; mask-composite:exclude; }}
      .cap-text {{ position:relative; z-index:1; font-size:{FS}px; font-weight:800;
                   line-height:1.24; color:#fff; text-align:center;
                   text-shadow:0 2px 14px rgba(0,0,0,0.6); }}
    </style>
  </head>
  <body>
    <div id="root" data-composition-id="main" data-start="0" data-duration="{DUR}"
         data-width="{W}" data-height="{SH}" data-fps="60">
      <div id="track" class="clip" data-start="0" data-duration="{DUR}" data-track-index="1">
        <div id="stage" aria-hidden="true"></div>
      </div>
    </div>
    <script src="cues.js"></script>
    <script>
      (function () {{
        var stage = document.getElementById("stage");
        CUES.forEach(function (cue, i) {{
          var item = document.createElement("div");
          item.className = "cap-item"; item.id = "cap-" + i;
          var pill = document.createElement("div"); pill.className = "cap-pill";
          var t = document.createElement("span"); t.className = "cap-text";
          t.textContent = cue.t; pill.appendChild(t); item.appendChild(pill);
          stage.appendChild(item);
        }});
        window.__timelines = window.__timelines || {{}};
        var tl = gsap.timeline({{ paused: true }});
        CUES.forEach(function (cue, i) {{
          var sel = "#cap-" + i, d = cue.e - cue.s;
          var pop = Math.min(0.08, Math.max(0.035, d * 0.35));
          tl.fromTo(sel, {{ opacity:0, scale:0.92 }},
            {{ opacity:1, scale:1, duration:pop, ease:"back.out(2.4)" }}, cue.s);
          tl.set(sel, {{ opacity:0 }}, cue.e);
        }});
        tl.to({{}}, {{ duration: CUES_DURATION }}, 0);
        window.__timelines["main"] = tl;
      }})();
    </script>
  </body>
</html>
"""


def run(cmd, label):
    r = subprocess.run(cmd)
    if r.returncode != 0:
        print("FAILED:", label)
        sys.exit(1)


def decoded_samples(p: Path) -> int:
    r = subprocess.run(["ffmpeg", "-v", "error", "-i", str(p), "-map", "0:a",
                        "-f", "s16le", "-ac", "1", "-ar", "48000", "-"],
                       capture_output=True)
    return len(r.stdout) // 2


def build_cues(name: str) -> list[dict]:
    spec = SHORTS[name]
    d = OUT_DIR / name
    starts = json.loads((d / "starts.json").read_text(encoding="utf-8"))
    words = [w for w in json.loads(
        (EDIT / "transcripts" / "webcam_captions.json").read_text(encoding="utf-8"))["words"]]
    cues = []
    for i, c in enumerate(spec["clips"]):
        base = starts[i]
        inr = [w for w in words if c["start"] - 0.05 <= w["start"] < c["end"] + 0.05]
        chunk, prev = [], None
        made = []
        for w in inr:
            gap = (w["start"] - prev) if prev is not None else 0.0
            if chunk and (gap >= GAP_BREAK or len(chunk) >= MAX_CHUNK):
                made.append(chunk); chunk = []
            chunk.append(w); prev = w["end"]
            if w["text"].rstrip()[-1:] in ".!?":
                made.append(chunk); chunk = []
        if chunk:
            made.append(chunk)
        for ch in made:
            if not ch:
                continue
            cues.append(dict(s=round(base + ch[0]["start"] - c["start"], 3),
                             e=round(base + ch[-1]["end"] - c["start"], 3),
                             t=" ".join(x["text"] for x in ch)))
    cues.sort(key=lambda c: c["s"])
    for i in range(len(cues) - 1):
        if cues[i + 1]["s"] < cues[i]["e"]:
            cues[i]["e"] = cues[i + 1]["s"]
        if cues[i]["e"] <= cues[i]["s"]:
            cues[i]["e"] = cues[i]["s"] + 0.05
    return cues


def main():
    name = sys.argv[1] if len(sys.argv) > 1 else "glow"
    d = OUT_DIR / name
    silent = d / "silent.mp4"
    cues = build_cues(name)
    dur = round(cues[-1]["e"] + 0.6, 2)
    print(f"{len(cues)} cues, last ends {cues[-1]['e']:.2f}s")
    longest = max(cues, key=lambda c: len(c["t"]))
    print(f"longest: {len(longest['t'])} chars -- {longest['t']!r}")

    slot = ANIM / f"slot_short_{name}_caps"
    slot.mkdir(exist_ok=True)
    for f in ("hyperframes.json", "AGENTS.md", "CLAUDE.md"):
        if (DONOR / f).exists():
            shutil.copy(DONOR / f, slot / f)
    pkg = json.loads((DONOR / "package.json").read_text(encoding="utf-8"))
    pkg["name"] = slot.name
    (slot / "package.json").write_text(json.dumps(pkg, indent=2) + "\n", encoding="utf-8")
    (slot / "meta.json").write_text(json.dumps({"id": slot.name, "name": slot.name},
                                               indent=2) + "\n", encoding="utf-8")
    (slot / "cues.js").write_text(
        f"var CUES = {json.dumps(cues)};\nvar CUES_DURATION = {dur};\n", encoding="utf-8")
    (slot / "index.html").write_text(
        HTML.format(W=W, SH=STRIP_H, PB=PILL_BOTTOM, MW=MAX_WIDTH, FS=FONT_PX, DUR=dur),
        encoding="utf-8")
    print(f"caption slot -> {slot}")

    if "--render" not in sys.argv:
        print("(pass --render to render + finalize)")
        return

    run(["npx", "--yes", "hyperframes@0.8.3", "render", "--format", "webm",
         "-o", "render.webm", str(slot)], "caption render")

    ref = decoded_samples(silent)
    r = subprocess.run(["ffmpeg", "-hide_banner", "-i", str(silent), "-map", "0:a",
                        "-af", f"loudnorm=I={TARGET_I}:TP={TARGET_TP}:LRA={TARGET_LRA}"
                               ":print_format=json", "-f", "null", "-"],
                       capture_output=True, text=True)
    m = json.loads(re.findall(r"\{[^{}]*\"input_i\"[^{}]*\}", r.stderr, re.S)[-1])
    print(f"loudness in: I={m['input_i']} TP={m['input_tp']} LRA={m['input_lra']}")

    tmp_v, tmp_a = d / "_v.mp4", d / "_a.m4a"
    run(["ffmpeg", "-y", "-v", "error", "-stats", "-i", str(silent),
         "-c:v", "libvpx-vp9", "-i", str(slot / "render.webm"),
         "-filter_complex", f"[0:v][1:v]overlay=x=0:y={STRIP_Y}:eof_action=pass[v]",
         "-map", "[v]", "-an", "-c:v", "libx264", "-preset", "medium", "-crf", "19",
         "-pix_fmt", "yuv420p", "-r", "60", str(tmp_v)], "video")
    af = (f"loudnorm=I={TARGET_I}:TP={TARGET_TP}:LRA={TARGET_LRA}"
          f":measured_I={m['input_i']}:measured_TP={m['input_tp']}"
          f":measured_LRA={m['input_lra']}:measured_thresh={m['input_thresh']}"
          f":offset={m['target_offset']}:linear=true,aresample=48000")
    run(["ffmpeg", "-y", "-v", "error", "-i", str(silent), "-map", "0:a", "-af", af,
         "-c:a", "aac", "-b:a", "192k", "-ar", "48000", "-ac", "2", str(tmp_a)], "audio")

    got = decoded_samples(tmp_a)
    if abs(got - ref) > 48000 * 0.25:
        print(f"ABORT: audio lost {(ref-got)/48000:.2f}s")
        sys.exit(1)
    out = d / f"short_{name}.mp4"
    run(["ffmpeg", "-y", "-v", "error", "-i", str(tmp_v), "-i", str(tmp_a),
         "-map", "0:v:0", "-map", "1:a:0", "-c", "copy",
         "-movflags", "+faststart", str(out)], "mux")
    fin = decoded_samples(out)
    print(f"\naudio delta {fin-ref:+d} samples")
    tmp_v.unlink(missing_ok=True); tmp_a.unlink(missing_ok=True)
    print(f"done: {out}")


if __name__ == "__main__":
    main()

