            cues.append(dict(s=round(base + ch[0]["start"] - c["start"], 3),
                             e=round(base + ch[-1]["end"] - c["start"], 3),
                             t=" ".join(x["text"] for x in ch)))
    cues.sort(key=lambda c: c["s"])
    for i in range(len(cues) - 1):
        if cues[i + 1]["s"] < cues[i]["e"]:
            cues[i]["e"] = cues[i + 1]["s"]
        if cues[i]["e"] <= cues[i]["s"]:
            cues[i]["e"] = cues[i]["s"] + 0.05
    return cues


def main():
    name = sys.argv[1] if len(sys.argv) > 1 else "glow"
    d = OUT_DIR / name
    silent = d / "silent.mp4"
    cues = build_cues(name)
    dur = round(cues[-1]["e"] + 0.6, 2)
    print(f"{len(cues)} cues, last ends {cues[-1]['e']:.2f}s")
    longest = max(cues, key=lambda c: len(c["t"]))
    print(f"longest: {len(longest['t'])} chars -- {longest['t']!r}")

    slot = ANIM / f"slot_short_{name}_caps"
    slot.mkdir(exist_ok=True)
    for f in ("hyperframes.json", "AGENTS.md", "CLAUDE.md"):
        if (DONOR / f).exists():
            shutil.copy(DONOR / f, slot / f)
    pkg = json.loads((DONOR / "package.json").read_text(encoding="utf-8"))
    pkg["name"] = slot.name
    (slot / "package.json").write_text(json.dumps(pkg, indent=2) + "\n", encoding="utf-8")
    (slot / "meta.json").write_text(json.dumps({"id": slot.name, "name": slot.name},
                                               indent=2) + "\n", encoding="utf-8")
    (slot / "cues.js").write_text(
        f"var CUES = {json.dumps(cues)};\nvar CUES_DURATION = {dur};\n", encoding="utf-8")
    (slot / "index.html").write_text(
        HTML.format(W=W, SH=STRIP_H, PB=PILL_BOTTOM, MW=MAX_WIDTH, FS=FONT_PX, DUR=dur),
        encoding="utf-8")
    print(f"caption slot -> {slot}")

    if "--render" not in sys.argv:
        print("(pass --render to render + finalize)")
        return

    run(["npx", "--yes", "hyperframes@0.8.3", "render", "--format", "webm",
         "-o", "render.webm", str(slot)], "caption render")

    ref = decoded_samples(silent)
    r = subprocess.run(["ffmpeg", "-hide_banner", "-i", str(silent), "-map", "0:a",
                        "-af", f"loudnorm=I={TARGET_I}:TP={TARGET_TP}:LRA={TARGET_LRA}"
                               ":print_format=json", "-f", "null", "-"],
                       capture_output=True, text=True)
    m = json.loads(re.findall(r"\{[^{}]*\"input_i\"[^{}]*\}", r.stderr, re.S)[-1])
    print(f"loudness in: I={m['input_i']} TP={m['input_tp']} LRA={m['input_lra']}")

    tmp_v, tmp_a = d / "_v.mp4", d / "_a.m4a"
    run(["ffmpeg", "-y", "-v", "error", "-stats", "-i", str(silent),
         "-c:v", "libvpx-vp9", "-i", str(slot / "render.webm"),
         "-filter_complex", f"[0:v][1:v]overlay=x=0:y={STRIP_Y}:eof_action=pass[v]",
         "-map", "[v]", "-an", "-c:v", "libx264", "-preset", "medium", "-crf", "19",
         "-pix_fmt", "yuv420p", "-r", "60", str(tmp_v)], "video")
    af = (f"loudnorm=I={TARGET_I}:TP={TARGET_TP}:LRA={TARGET_LRA}"
          f":measured_I={m['input_i']}:measured_TP={m['input_tp']}"
          f":measured_LRA={m['input_lra']}:measured_thresh={m['input_thresh']}"
          f":offset={m['target_offset']}:linear=true,aresample=48000")
    run(["ffmpeg", "-y", "-v", "error", "-i", str(silent), "-map", "0:a", "-af", af,
         "-c:a", "aac", "-b:a", "192k", "-ar", "48000", "-ac", "2", str(tmp_a)], "audio")

    got = decoded_samples(tmp_a)
    if abs(got - ref) > 48000 * 0.25:
        print(f"ABORT: audio lost {(ref-got)/48000:.2f}s")
        sys.exit(1)
    out = d / f"short_{name}.mp4"
    run(["ffmpeg", "-y", "-v", "error", "-i", str(tmp_v), "-i", str(tmp_a),
         "-map", "0:v:0", "-map", "1:a:0", "-c", "copy",
         "-movflags", "+faststart", str(out)], "mux")
    fin = decoded_samples(out)
    print(f"\naudio delta {fin-ref:+d} samples")
    tmp_v.unlink(missing_ok=True); tmp_a.unlink(missing_ok=True)
    print(f"done: {out}")


if __name__ == "__main__":
    main()

