// Scene: poster_grid_games
// ID: c43e4ae7-7f40-4e72-97a0-8a61f8dad9eb

const { AbsoluteFill, interpolate, Easing, useCurrentFrame, useVideoConfig } = window.Remotion;

const colors_muidpxde = [
  "#1e1b4b", "#172554", "#14213d", "#1a1a2e", "#0f2027",
  "#1b1f3b", "#0d1b2a", "#162032", "#1c1917", "#0a1628",
];

export default function Scene_muidpxde() {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const cols = 6;
  const rows = 3;
  const tileW = 280;
  const tileH = 160;
  const gap = 12;
  const gridW = cols * tileW + (cols - 1) * gap;
  const gridH = rows * tileH + (rows - 1) * gap;

  const driftX = Math.sin((frame / 90) * Math.PI) * 6;
  const driftY = Math.cos((frame / 90) * Math.PI) * 6;

  const overlayOpacity = interpolate(frame, [45, 60], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const overlayScale = interpolate(frame, [45, 60], [0.92, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const tiles = Array.from({ length: 18 });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "#05060d",
        fontFamily: "Geist, sans-serif",
        overflow: "hidden",
      }}
    >
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700;800&family=Geist+Mono:wght@400;500;600&display=swap');`}</style>

      <div
        style={{
          position: "absolute",
          left: (width - gridW) / 2,
          top: (height - gridH) / 2,
          width: gridW,
          height: gridH,
          display: "grid",
          gridTemplateColumns: `repeat(${cols}, ${tileW}px)`,
          gridTemplateRows: `repeat(${rows}, ${tileH}px)`,
          gap,
          transform: `translate(${driftX}px, ${driftY}px)`,
        }}
      >
        {tiles.map((_, i) => {
          const col = i % cols;
          const isEarlyCol = col % 2 === 0;
          const baseStart = i * 3 - 8 - (isEarlyCol ? 3 : 0);
          const dur = 12;
          const scale = interpolate(frame, [baseStart, baseStart + dur], [0.85, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });
          const opacity = interpolate(frame, [baseStart, baseStart + dur], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });
          const baseColor = colors_muidpxde[i % colors_muidpxde.length];

          return (
            <div
              key={i}
              style={{
                position: "relative",
                width: tileW,
                height: tileH,
                borderRadius: 10,
                border: "1px solid rgba(139,112,251,0.25)",
                background: `linear-gradient(180deg, rgba(0,0,0,0.28) 0%, rgba(255,255,255,0.04) 100%), ${baseColor}`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                overflow: "hidden",
                opacity,
                transform: `scale(${scale})`,
              }}
            >
              <window.IconifyIcon
                icon="mdi:gamepad-variant-outline"
                style={{ fontSize: 32, color: "rgba(255,255,255,0.4)" }}
              />
              <div
                style={{
                  position: "absolute",
                  left: 10,
                  bottom: 8,
                  fontFamily: "'Geist Mono', monospace",
                  fontSize: 11,
                  color: "rgba(255,255,255,0.5)",
                  letterSpacing: 0.3,
                }}
              >
                {`Game ${i + 1}`}
              </div>
            </div>
          );
        })}
      </div>

      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(circle at 50% 50%, transparent 40%, rgba(0,0,0,0.5) 100%)",
          pointerEvents: "none",
        }}
      />

      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%) scale(${overlayScale})`,
          opacity: overlayOpacity,
          textAlign: "center",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 8,
        }}
      >
        <div style={{ display: "flex", alignItems: "baseline", gap: 16 }}>
          <span
            style={{
              fontFamily: "Geist, sans-serif",
              fontWeight: 800,
              fontSize: 120,
              color: "#ffffff",
              textShadow: "0 0 40px rgba(107,71,245,0.8)",
            }}
          >
            47+
          </span>
          <span
            style={{
              fontFamily: "Geist, sans-serif",
              fontWeight: 600,
              fontSize: 80,
              color: "#ffffff",
              textShadow: "0 0 40px rgba(107,71,245,0.8)",
            }}
          >
            games
          </span>
        </div>
        <div
          style={{
            fontFamily: "'Geist Mono', monospace",
            fontSize: 22,
            color: "#22d3ee",
            letterSpacing: 1,
          }}
        >
          and counting
        </div>
      </div>
    </AbsoluteFill>
  );
}

export const durationInFrames_muidpxde = 90;

// Scene: poster_grid_mods
// ID: 5ee6aed5-0437-4175-a93d-4d7872eac226

const { AbsoluteFill, interpolate, Easing, useCurrentFrame, useVideoConfig } = window.Remotion;

const tileColors_muidukf6 = [
  "#1e1b4b", "#172554", "#14213d", "#1a1a2e",
  "#0f2027", "#1b1f3b", "#0d1b2a", "#162032",
];

const tileIcons_muidukf6 = [
  "mdi:puzzle-outline",
  "mdi:wrench-outline",
  "mdi:package-variant",
];

export default function Scene_muidukf6() {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const cols = 8;
  const rows = 5;
  const tileSize = 190;
  const gap = 10;
  const gridW = cols * tileSize + (cols - 1) * gap;
  const gridH = rows * tileSize + (rows - 1) * gap;

  const driftX = Math.sin((frame / 90) * Math.PI) * 6;
  const driftY = Math.cos((frame / 90) * Math.PI) * 6;

  const overlayOpacity = interpolate(frame, [30, 48], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const overlayScale = interpolate(frame, [30, 48], [0.92, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const rawCounter = interpolate(frame, [0, 75], [60000, 70000], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.exp),
  });
  const counterValue = Math.round(rawCounter);
  const counterDisplay =
    counterValue >= 70000 ? "70,000+" : counterValue.toLocaleString();

  const tiles = Array.from({ length: cols * rows });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "#05060d",
        fontFamily: "Geist, sans-serif",
        overflow: "hidden",
      }}
    >
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700;800&family=Geist+Mono:wght@400;500;600&display=swap');`}</style>

      <div
        style={{
          position: "absolute",
          left: (width - gridW) / 2 + driftX,
          top: (height - gridH) / 2 + driftY,
          width: gridW,
          height: gridH,
          display: "grid",
          gridTemplateColumns: `repeat(${cols}, ${tileSize}px)`,
          gridTemplateRows: `repeat(${rows}, ${tileSize}px)`,
          gap,
        }}
      >
        {tiles.map((_, i) => {
          const baseStart = i * 2.5;
          const dur = 12;
          const scale = interpolate(frame, [baseStart, baseStart + dur], [0.85, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });
          const opacity = interpolate(frame, [baseStart, baseStart + dur], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });

          const baseColor = tileColors_muidukf6[i % tileColors_muidukf6.length];
          const icon = tileIcons_muidukf6[i % tileIcons_muidukf6.length];
          const label = `mod-${String(i + 1).padStart(3, "0")}`;

          return (
            <div
              key={i}
              style={{
                position: "relative",
                width: tileSize,
                height: tileSize,
                borderRadius: 10,
                border: "1px solid rgba(139,112,251,0.25)",
                background: `linear-gradient(180deg, rgba(0,0,0,0.28) 0%, rgba(255,255,255,0.04) 100%), ${baseColor}`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                overflow: "hidden",
                opacity,
                transform: `scale(${scale})`,
              }}
            >
              <window.IconifyIcon
                icon={icon}
                style={{ fontSize: 36, color: "rgba(255,255,255,0.45)" }}
              />
              <div
                style={{
                  position: "absolute",
                  left: 8,
                  bottom: 6,
                  fontFamily: "'Geist Mono', monospace",
                  fontSize: 10,
                  color: "rgba(255,255,255,0.45)",
                  letterSpacing: 0.2,
                }}
              >
                {label}
              </div>
            </div>
          );
        })}
      </div>

      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(circle at 50% 50%, transparent 40%, rgba(0,0,0,0.5) 100%)",
          pointerEvents: "none",
        }}
      />

      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%) scale(${overlayScale})`,
          opacity: overlayOpacity,
          textAlign: "center",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          padding: "32px 60px 36px",
          background: "radial-gradient(ellipse at 50% 50%, rgba(5,6,13,0.72) 60%, transparent 100%)",
          borderRadius: 24,
        }}
      >
        <div
