        {tiles.map((_, i) => {
          const baseStart = i * 2.5;
          const dur = 12;
          const scale = interpolate(frame, [baseStart, baseStart + dur], [0.85, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });
          const opacity = interpolate(frame, [baseStart, baseStart + dur], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });

          const baseColor = tileColors_muidukf6[i % tileColors_muidukf6.length];
          const icon = tileIcons_muidukf6[i % tileIcons_muidukf6.length];
          const label = `mod-${String(i + 1).padStart(3, "0")}`;

          return (
            <div
              key={i}
              style={{
                position: "relative",
                width: tileSize,
                height: tileSize,
                borderRadius: 10,
                border: "1px solid rgba(139,112,251,0.25)",
                background: `linear-gradient(180deg, rgba(0,0,0,0.28) 0%, rgba(255,255,255,0.04) 100%), ${baseColor}`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                overflow: "hidden",
                opacity,
                transform: `scale(${scale})`,
              }}
            >
              <Icon
                icon={icon}
                style={{ fontSize: 36, color: "rgba(255,255,255,0.45)" }}
              />
              <div
                style={{
                  position: "absolute",
                  left: 8,
                  bottom: 6,
                  fontFamily: "'Geist Mono', monospace",
                  fontSize: 10,
                  color: "rgba(255,255,255,0.45)",
                  letterSpacing: 0.2,
                }}
              >
                {label}
              </div>
            </div>
          );
        })}
      </div>

      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(circle at 50% 50%, transparent 40%, rgba(0,0,0,0.5) 100%)",
          pointerEvents: "none",
        }}
      />

      <div
        style={{
          position: "absolute",
