  const { width, height } = useVideoConfig();

  const cols = 8;
  const rows = 5;
  const tileSize = 190;
  const gap = 10;
  const gridW = cols * tileSize + (cols - 1) * gap;
  const gridH = rows * tileSize + (rows - 1) * gap;

  const driftX = Math.sin((frame / 90) * Math.PI) * 6;
  const driftY = Math.cos((frame / 90) * Math.PI) * 6;

  const overlayOpacity = interpolate(frame, [30, 48], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const overlayScale = interpolate(frame, [30, 48], [0.92, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const rawCounter = interpolate(frame, [0, 75], [60000, 70000], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.exp),
  });
  const counterValue = Math.round(rawCounter);
