export default function DiscountReveal() {
  const frame = useCurrentFrame();

  const cardIn = interpolate(frame, [0, 16], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const cardScale = interpolate(frame, [0, 16], [0.92, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const pulse = 0.55 + 0.25 * Math.sin(Math.max(0, frame - 16) / 14);

  const eyebrowOp = interpolate(frame, [2, 12], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const pctOp = interpolate(frame, [10, 24], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const pctScale = interpolate(frame, [10, 26], [0.85, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.back(1.4)),
  });
  const subOp = interpolate(frame, [22, 32], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const dividerScale = interpolate(frame, [30, 40], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const footOp = interpolate(frame, [38, 50], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: "#05060d", overflow: "hidden" }}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700;800&family=Geist+Mono:wght@400;500;600&display=swap');`}</style>

      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: 900,
          height: 620,
          transform: "translate(-50%, -50%)",
          background: "radial-gradient(circle, rgba(111,71,245,0.35) 0%, rgba(111,71,245,0) 70%)",
          opacity: pulse,
          filter: "blur(10px)",
        }}
      />

      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%) scale(${cardScale})`,
          opacity: cardIn,
          width: 720,
          padding: "56px 64px",
          borderRadius: 28,
          border: "1px solid rgba(255,255,255,0.10)",
          background:
            "linear-gradient(180deg, rgba(20,18,38,0.85) 0%, rgba(10,9,20,0.9) 100%)",
          boxShadow: `0 0 90px rgba(111,71,245,${0.35 * pulse}), 0 30px 80px rgba(0,0,0,0.5)`,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          textAlign: "center",
        }}
      >
        <div
          style={{
            opacity: eyebrowOp,
            fontFamily: "'Geist Mono', monospace",
            fontSize: 18,
            letterSpacing: 4,
            color: "#22d3ee",
            fontWeight: 600,
            marginBottom: 18,
          }}
        >
          CREATOR PARTNER CODE
        </div>

        <div
          style={{
            opacity: pctOp,
            transform: `scale(${pctScale})`,
            fontFamily: "Geist, sans-serif",
            fontWeight: 800,
            fontSize: 128,
            lineHeight: 1,
            background: "linear-gradient(90deg, #3b82f6, #8a70fb, #6f47f5)",
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            color: "transparent",
            filter: "drop-shadow(0 0 46px rgba(107,71,245,0.55))",
          }}
        >
          50% OFF
        </div>

        <div
          style={{
            opacity: subOp,
            fontFamily: "Geist, sans-serif",
            fontWeight: 500,
            fontSize: 30,
            color: "#ffffff",
            marginTop: 14,
          }}
        >
          your first purchase
        </div>

        <div
          style={{
            transform: `scaleX(${dividerScale})`,
            width: 220,
            height: 1,
            background:
              "linear-gradient(90deg, transparent, rgba(255,255,255,0.25), transparent)",
            margin: "28px 0 24px",
          }}
        />

        <div
          style={{
            opacity: footOp,
            fontFamily: "Geist, sans-serif",
            fontWeight: 400,
            fontSize: 20,
            lineHeight: 1.5,
            color: "rgba(255,255,255,0.65)",
            maxWidth: 520,
          }}
        >
          10% off for life after that — upgrades, renewals, everything
        </div>
      </div>
    </AbsoluteFill>
  );
}

export const DURATION_DISCOUNT = 75;

