import { Composition } from "remotion";
import PosterGridGames, { DURATION_POSTER_GAMES } from "./scenes/PosterGridGames";
import PosterGridMods, { DURATION_POSTER_MODS } from "./scenes/PosterGridMods";
import DiscountReveal, { DURATION_DISCOUNT } from "./scenes/DiscountReveal";
import SupportCard, { DURATION_SUPPORT } from "./scenes/SupportCard";
import OutroCta, { DURATION_OUTRO } from "./scenes/OutroCta";

const FPS = 30;
const WIDTH = 1920;
const HEIGHT = 1080;

export const RemotionRoot: React.FC = () => {
  return (
    <>
      <Composition
        id="poster_grid_games"
        component={PosterGridGames}
        durationInFrames={DURATION_POSTER_GAMES}
        fps={FPS}
        width={WIDTH}
        height={HEIGHT}
      />
      <Composition
        id="poster_grid_mods"
        component={PosterGridMods}
        durationInFrames={DURATION_POSTER_MODS}
        fps={FPS}
        width={WIDTH}
        height={HEIGHT}
      />
      <Composition
        id="discount_reveal"
        component={DiscountReveal}
        durationInFrames={DURATION_DISCOUNT}
        fps={FPS}
        width={WIDTH}
        height={HEIGHT}
      />
      <Composition
        id="support_card"
        component={SupportCard}
        durationInFrames={DURATION_SUPPORT}
        fps={FPS}
        width={WIDTH}
        height={HEIGHT}
      />
      <Composition
        id="outro_cta"
        component={OutroCta}
        durationInFrames={DURATION_OUTRO}
        fps={FPS}
        width={WIDTH}
        height={HEIGHT}
