"""Build the 4 transparent HyperFrames text overlays that sit on top of the
live screen-recording footage (the poster/discount/mod/support/outro cards
are full-frame Remotion scenes and need no overlay -- these four are for the
in-between footage beats where the real product UI is doing the talking and
we just add a short callout).

All four share one visual system: a soft bottom scrim (so white text reads
over unpredictable UI colors underneath) and a lower-third text block in the
Nxeon brand palette. Kept intentionally quiet -- this is a product demo, the
UI is the star, these are captions not billboards.
"""
from __future__ import annotations

from pathlib import Path

EDIT = Path(__file__).resolve().parent.parent
ANIM = EDIT / "animations"

FONT_IMPORT = (
    "@import url('https://fonts.googleapis.com/css2?"
    "family=Geist:wght@400;500;600;700;800&family=Geist+Mono:wght@400;500;600&display=swap');"
)

BASE_CSS = """
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { width: 1920px; height: 1080px; overflow: hidden; background: transparent; }
body { font-family: 'Geist', sans-serif; }
#root { position: relative; width: 1920px; height: 1080px; background: transparent; }
.scrim {
  position: absolute; left: 0; right: 0; bottom: 0; height: 340px;
  background: linear-gradient(180deg, rgba(5,6,13,0) 0%, rgba(5,6,13,0.55) 100%);
  opacity: 0;
}
.accent {
  display: inline-block; width: 8px; height: 8px; border-radius: 50%;
  background: linear-gradient(120deg, #3b82f6, #8a70fb, #6f47f5);
  box-shadow: 0 0 12px rgba(111,71,245,0.8);
  margin-right: 14px; vertical-align: middle;
}
"""


def compose(name: str, duration: float, body_html: str, extra_css: str, js: str) -> str:
    return f"""<!doctype html>
<html lang="en" data-resolution="landscape">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=1920, height=1080" />
    <title>{name}</title>
    <script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script>
    <style>
      {FONT_IMPORT}
      {BASE_CSS}
      {extra_css}
    </style>
  </head>
  <body>
    <div id="root" data-composition-id="main" data-start="0" data-duration="{duration}"
         data-width="1920" data-height="1080" data-fps="60">
      <div class="clip" data-start="0" data-duration="{duration}" data-track-index="1"
           style="position:absolute; inset:0;">
        <div class="scrim" id="scrim"></div>
        {body_html}
      </div>
    </div>
    <script>
      window.__timelines = window.__timelines || {{}};
      const tl = gsap.timeline({{ paused: true }});
      tl.fromTo("#scrim", {{ opacity: 0 }}, {{ opacity: 1, duration: 0.35, ease: "power2.out" }}, 0);
      tl.to("#scrim", {{ opacity: 0, duration: 0.3, ease: "power1.in" }}, {duration} - 0.32);
      {js}
      window.__timelines["main"] = tl;
    </script>
  </body>
</html>
"""


def write(name: str, html: str):
    d = ANIM / name
    d.mkdir(parents=True, exist_ok=True)
    (d / "index.html").write_text(html, encoding="utf-8")
    print(f"  wrote {d / 'index.html'}")


def main():
    # 1. hook_text -- over the dashboard hero shot (1.60s)
    dur = 1.60
    body = """
        <div id="line" style="position:absolute; left:90px; bottom:150px; opacity:0;">
          <span class="accent"></span>
          <span style="font-weight:700; font-size:46px; color:#ffffff; letter-spacing:-0.5px;">
            Deploy a game server in seconds
          </span>
        </div>
    """
    js = """
      tl.fromTo("#line", { opacity: 0, y: 16 }, { opacity: 1, y: 0, duration: 0.4, ease: "power3.out" }, 0.12);
      tl.to("#line", { opacity: 0, y: -10, duration: 0.3, ease: "power1.in" }, %f - 0.34);
    """ % dur
    write("nx_hook_text", compose("hook_text", dur, body, "", js))

    # 2. player_note -- over the plan-selection footage (2.00s)
    dur = 2.00
    body = """
        <div id="line" style="position:absolute; left:90px; bottom:150px; opacity:0;">
          <span class="accent" style="background:linear-gradient(120deg,#11c88e,#22d3ee); box-shadow:0 0 12px rgba(17,200,142,0.7);"></span>
          <span style="font-weight:600; font-size:38px; color:#ffffff;">
            Player counts are a guide, not a limit
          </span>
        </div>
        <div id="sub" style="position:absolute; left:132px; bottom:110px; opacity:0;
             font-family:'Geist Mono', monospace; font-size:20px; color:rgba(255,255,255,0.6); letter-spacing:0.3px;">
          need more headroom? our team can build a custom size
        </div>
    """
    js = """
      tl.fromTo("#line", { opacity: 0, y: 16 }, { opacity: 1, y: 0, duration: 0.4, ease: "power3.out" }, 0.12);
      tl.fromTo("#sub", { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: 0.4, ease: "power2.out" }, 0.34);
      tl.to("#line, #sub", { opacity: 0, y: -10, duration: 0.3, ease: "power1.in" }, %f - 0.34);
    """ % dur
    write("nx_player_note", compose("player_note", dur, body, "", js))

    # 3. region_stat -- over the globe hero shot (2.80s), bottom-CENTER to match
    #    the globe's centred composition.
    dur = 2.80
    extra_css = """
      .center-wrap { position:absolute; left:50%; bottom:130px; transform:translateX(-50%); text-align:center; }
    """
    body = """
        <div id="stat" class="center-wrap" style="opacity:0;">
          <div style="font-family:'Geist', sans-serif; font-weight:800; font-size:56px; line-height:1;
               background:linear-gradient(90deg,#3b82f6,#8a70fb,#6f47f5); -webkit-background-clip:text;
               background-clip:text; color:transparent; filter:drop-shadow(0 0 26px rgba(107,71,245,0.6));">
            14 data centers &middot; 4 continents
          </div>
          <div id="sub" style="margin-top:10px; font-family:'Geist Mono', monospace; font-size:22px;
               color:#22d3ee; letter-spacing:0.5px; opacity:0;">
            the fastest ping for your community
          </div>
        </div>
    """
    js = """
      tl.fromTo("#stat", { opacity: 0, y: 16 }, { opacity: 1, y: 0, duration: 0.45, ease: "power3.out" }, 0.15);
      tl.fromTo("#sub", { opacity: 0 }, { opacity: 1, duration: 0.4, ease: "power2.out" }, 0.45);
      tl.to("#stat", { opacity: 0, y: -10, duration: 0.3, ease: "power1.in" }, %f - 0.34);
    """ % dur
    write("nx_region_stat", compose("region_stat", dur, body, extra_css, js))

    # 4. dashboard_lower_third -- over the live-dashboard footage (2.10s)
    dur = 2.10
    body = """
        <div id="line" style="position:absolute; left:90px; bottom:150px; opacity:0;
             font-family:'Geist', sans-serif; font-weight:600; font-size:36px; color:#ffffff;
             display:flex; align-items:center;">
          <span class="accent"></span>
          <span>Console</span>
          <span style="margin:0 16px; color:rgba(255,255,255,0.35);">&middot;</span>
          <span>Player counts</span>
          <span style="margin:0 16px; color:rgba(255,255,255,0.35);">&middot;</span>
          <span>One-click mod installs</span>
        </div>
    """
    js = """
      tl.fromTo("#line", { opacity: 0, y: 16 }, { opacity: 1, y: 0, duration: 0.4, ease: "power3.out" }, 0.12);
      tl.to("#line", { opacity: 0, y: -10, duration: 0.3, ease: "power1.in" }, %f - 0.34);
    """ % dur
    write("nx_dashboard_lt", compose("dashboard_lt", dur, body, "", js))


if __name__ == "__main__":
    main()

