import { AbsoluteFill, interpolate, Easing, staticFile, useCurrentFrame, useVideoConfig } from "remotion";

const N_COVERS = 29;
const COVERS = Array.from({ length: N_COVERS }, (_, i) => `games/g${String(i).padStart(2, "0")}.jpg`);

export default function PosterGridGames() {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const cols = 9;
  const rows = 3;
  const tileW = 168;
  const tileH = 224;
  const gap = 10;
  const gridW = cols * tileW + (cols - 1) * gap;
  const gridH = rows * tileH + (rows - 1) * gap;
  const slots = cols * rows; // 27 -- shows all but 2 of the 29 covers

  const driftX = Math.sin((frame / 100) * Math.PI) * 5;
  const driftY = Math.cos((frame / 100) * Math.PI) * 5;

  // "coming into focus" reveal -- blur-to-sharp plus scale, reads more
  // cinematic than a flat fade.
  const overlayOpacity = interpolate(frame, [42, 62], [0, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });
  const overlayScale = interpolate(frame, [42, 66], [1.12, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });
  const overlayBlur = interpolate(frame, [42, 62], [10, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp",
  });

  const tiles = Array.from({ length: slots });

  return (
    <AbsoluteFill style={{ backgroundColor: "#05060d", fontFamily: "Geist, sans-serif", overflow: "hidden" }}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700;800&family=Geist+Mono:wght@400;500;600&display=swap');`}</style>

      <div
        style={{
          position: "absolute",
          left: (width - gridW) / 2,
          top: (height - gridH) / 2,
          width: gridW,
          height: gridH,
          display: "grid",
          gridTemplateColumns: `repeat(${cols}, ${tileW}px)`,
          gridTemplateRows: `repeat(${rows}, ${tileH}px)`,
          gap,
          transform: `translate(${driftX}px, ${driftY}px)`,
        }}
      >
        {tiles.map((_, i) => {
          const baseStart = i * 2.2 - 6;
          const dur = 14;
          const scale = interpolate(frame, [baseStart, baseStart + dur], [0.85, 1], {
            extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
          });
          const opacity = interpolate(frame, [baseStart, baseStart + dur], [0, 1], {
            extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
          });

          return (
            <div
              key={i}
              style={{
                position: "relative",
                width: tileW,
                height: tileH,
                borderRadius: 10,
                overflow: "hidden",
                border: "1px solid rgba(139,112,251,0.30)",
                boxShadow: "0 6px 18px rgba(0,0,0,0.45)",
                opacity,
                transform: `scale(${scale})`,
              }}
            >
              <img
                src={staticFile(COVERS[i % COVERS.length])}
                style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
              />
              <div
                style={{
                  position: "absolute", inset: 0,
                  background: "linear-gradient(180deg, rgba(0,0,0,0.05) 0%, rgba(0,0,0,0.35) 100%)",
                }}
              />
            </div>
          );
        })}
      </div>

      <div
        style={{
          position: "absolute", inset: 0,
          background: "radial-gradient(circle at 50% 50%, transparent 28%, rgba(5,6,13,0.55) 68%, rgba(5,6,13,0.85) 100%)",
          pointerEvents: "none",
        }}
      />

      <div
        style={{
          position: "absolute", left: "50%", top: "50%",
          transform: `translate(-50%, -50%) scale(${overlayScale})`,
          opacity: overlayOpacity,
          filter: `blur(${overlayBlur}px)`,
          textAlign: "center",
          display: "flex", flexDirection: "column", alignItems: "center", gap: 10,
          padding: "34px 66px 40px",
          background: "radial-gradient(ellipse at 50% 50%, rgba(5,6,13,0.78) 55%, transparent 100%)",
          borderRadius: 28,
        }}
      >
        <div style={{ display: "flex", alignItems: "baseline", gap: 18 }}>
          <span
            style={{
              fontFamily: "Geist, sans-serif", fontWeight: 800, fontSize: 132,
              background: "linear-gradient(90deg, #3b82f6, #8a70fb, #6f47f5)",
              WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent",
              filter: "drop-shadow(0 0 44px rgba(107,71,245,0.65))",
              letterSpacing: -2,
            }}
          >
            47+
          </span>
          <span style={{ fontFamily: "Geist, sans-serif", fontWeight: 700, fontSize: 84, color: "#ffffff" }}>
            games
          </span>
        </div>
        <div
          style={{
            fontFamily: "'Geist Mono', monospace", fontSize: 24, color: "#22d3ee",
            letterSpacing: 3, textTransform: "uppercase",
          }}
        >
          and counting
        </div>
      </div>
    </AbsoluteFill>
  );
}

export const DURATION_POSTER_GAMES = 102; // 3.4s @ 30fps

