          gridTemplateColumns: `repeat(${cols}, ${tileW}px)`,
          gridTemplateRows: `repeat(${rows}, ${tileH}px)`,
          gap,
          transform: `translate(${driftX}px, ${driftY}px)`,
        }}
      >
        {tiles.map((_, i) => {
          const col = i % cols;
          const isEarlyCol = col % 2 === 0;
          const baseStart = i * 3 - 8 - (isEarlyCol ? 3 : 0);
          const dur = 12;
          const scale = interpolate(frame, [baseStart, baseStart + dur], [0.85, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });
          const opacity = interpolate(frame, [baseStart, baseStart + dur], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });
          const baseColor = colors_muidpxde[i % colors_muidpxde.length];

          return (
            <div
              key={i}
              style={{
                position: "relative",
                width: tileW,
                height: tileH,
                borderRadius: 10,
                border: "1px solid rgba(139,112,251,0.25)",
                background: `linear-gradient(180deg, rgba(0,0,0,0.28) 0%, rgba(255,255,255,0.04) 100%), ${baseColor}`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                overflow: "hidden",
                opacity,
                transform: `scale(${scale})`,
              }}
            >
              <Icon
                icon="mdi:gamepad-variant-outline"
                style={{ fontSize: 32, color: "rgba(255,255,255,0.4)" }}
              />
              <div
                style={{
                  position: "absolute",
                  left: 10,
                  bottom: 8,
                  fontFamily: "'Geist Mono', monospace",
                  fontSize: 11,
                  color: "rgba(255,255,255,0.5)",
                  letterSpacing: 0.3,
                }}
              >
                {`Game ${i + 1}`}
              </div>
            </div>
          );
        })}
      </div>

      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(circle at 50% 50%, transparent 40%, rgba(0,0,0,0.5) 100%)",
          pointerEvents: "none",
        }}
      />

      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%) scale(${overlayScale})`,
          opacity: overlayOpacity,
          textAlign: "center",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 8,
        }}
      >
        <div style={{ display: "flex", alignItems: "baseline", gap: 16 }}>
          <span
            style={{
              fontFamily: "Geist, sans-serif",
              fontWeight: 800,
              fontSize: 120,
              color: "#ffffff",
              textShadow: "0 0 40px rgba(107,71,245,0.8)",
            }}
          >
            47+
          </span>
          <span
            style={{
              fontFamily: "Geist, sans-serif",
              fontWeight: 600,
              fontSize: 80,
              color: "#ffffff",
              textShadow: "0 0 40px rgba(107,71,245,0.8)",
            }}
          >
            games
          </span>
        </div>
        <div
          style={{
            fontFamily: "'Geist Mono', monospace",
            fontSize: 22,
            color: "#22d3ee",
            letterSpacing: 1,
          }}
        >
          and counting
        </div>
      </div>
    </AbsoluteFill>
  );
}

export const DURATION_POSTER_GAMES = 90;

