import { AbsoluteFill, Img, interpolate, Easing, staticFile, useCurrentFrame } from "remotion";

export default function OutroCta() {
  const frame = useCurrentFrame();

  // --- ambient background: two slow-drifting colour orbs + a pulsing core
  // glow behind the logo, instead of one static blob sitting in a lot of
  // dead space.
  const driftA = Math.sin(frame / 70) * 40;
  const driftB = Math.cos(frame / 85) * 40;
  const pulse = 0.55 + 0.25 * Math.sin(frame / 20);

  // --- one diagonal light sheen sweeps across the frame early, like a
  // logo sting -- a classic "premium reveal" cue.
  const sweepX = interpolate(frame, [4, 30], [-700, 2400], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.cubic),
  });
  const sweepOp = interpolate(frame, [4, 12, 26, 30], [0, 0.5, 0.5, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp",
  });

  const logoOp = interpolate(frame, [0, 16], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const logoScale = interpolate(frame, [0, 20], [0.7, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.back(1.4)),
  });
  const ringScale = interpolate(frame, [0, 28], [0.6, 1.35], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });
  const ringOp = interpolate(frame, [0, 14, 28], [0.9, 0.35, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // headline: letter-spacing pulls IN as it fades up -- a more "epic
  // trailer title" reveal than a plain fade.
  const headOp = interpolate(frame, [20, 38], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const headY = interpolate(frame, [20, 38], [22, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });
  const headTrack = interpolate(frame, [20, 42], [14, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });

  const dividerScale = interpolate(frame, [42, 54], [0, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });

  const pillsOp = interpolate(frame, [50, 64], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const pill1Y = interpolate(frame, [50, 64], [16, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.back(1.5)),
  });
  const pill2Y = interpolate(frame, [58, 72], [16, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.back(1.5)),
  });
  const pill2Op = interpolate(frame, [58, 72], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "#05060d", overflow: "hidden",
        display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
      }}
    >
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700;800&family=Geist+Mono:wght@400;500;600&display=swap');`}</style>

      {/* ambient orbs */}
      <div style={{
        position: "absolute", left: 260 + driftA, top: 220 + driftB, width: 560, height: 560,
        borderRadius: "50%", background: "radial-gradient(circle, rgba(59,130,246,0.22) 0%, rgba(59,130,246,0) 70%)",
        filter: "blur(6px)",
      }} />
      <div style={{
        position: "absolute", right: 220 - driftA, bottom: 160 - driftB, width: 620, height: 620,
        borderRadius: "50%", background: "radial-gradient(circle, rgba(111,71,245,0.20) 0%, rgba(111,71,245,0) 70%)",
        filter: "blur(6px)",
      }} />
      {/* core glow behind logo */}
      <div style={{
        position: "absolute", left: "50%", top: "33%", width: 900, height: 620,
        transform: "translate(-50%, -50%)",
        background: "radial-gradient(circle, rgba(138,112,251,0.34) 0%, rgba(111,71,245,0) 70%)",
        opacity: pulse,
      }} />

      {/* diagonal sheen sweep */}
      <div style={{
        position: "absolute", top: -200, left: sweepX, width: 260, height: 1500,
        transform: "rotate(18deg)",
        background: "linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.14) 50%, rgba(255,255,255,0) 100%)",
        opacity: sweepOp,
        pointerEvents: "none",
      }} />

      {/* logo + pulsing ring */}
      <div style={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{
          position: "absolute", width: 260, height: 260, borderRadius: "50%",
          border: "1.5px solid rgba(138,112,251,0.6)",
          transform: `scale(${ringScale})`, opacity: ringOp,
        }} />
        <Img
          src={staticFile("nxeon-logo.png")}
          style={{ width: 280, opacity: logoOp, transform: `scale(${logoScale})`, zIndex: 2 }}
        />
      </div>

      <div
        style={{
          opacity: headOp, transform: `translateY(${headY}px)`,
          marginTop: 40, fontFamily: "Geist, sans-serif", fontWeight: 800, fontSize: 66,
          color: "#ffffff", textAlign: "center", zIndex: 2,
          letterSpacing: `${headTrack}px`,
        }}
      >
        Deploy your game server today
      </div>

      <div style={{
        transform: `scaleX(${dividerScale})`, width: 140, height: 2, marginTop: 30, marginBottom: 26,
        background: "linear-gradient(90deg, transparent, rgba(138,112,251,0.7), transparent)",
      }} />

      <div style={{ display: "flex", gap: 18, zIndex: 2 }}>
        <div style={{
          opacity: pillsOp, transform: `translateY(${pill1Y}px)`,
          padding: "14px 30px", borderRadius: 999,
          background: "linear-gradient(90deg, rgba(59,130,246,0.16), rgba(138,112,251,0.16))",
          border: "1px solid rgba(138,112,251,0.4)",
          fontFamily: "'Geist Mono', monospace", fontSize: 24, color: "#ffffff",
        }}>
          <span style={{ color: "#3b82f6", fontWeight: 700 }}>50% off</span> first purchase
        </div>
        <div style={{
          opacity: pill2Op, transform: `translateY(${pill2Y}px)`,
          padding: "14px 30px", borderRadius: 999,
          background: "rgba(17,200,142,0.12)",
          border: "1px solid rgba(17,200,142,0.4)",
          fontFamily: "'Geist Mono', monospace", fontSize: 24, color: "#ffffff",
        }}>
          <span style={{ color: "#11c88e", fontWeight: 700 }}>10% off</span> for life
        </div>
      </div>
    </AbsoluteFill>
  );
}

export const DURATION_OUTRO = 96; // 3.2s @ 30fps

