            WebkitBackgroundClip: "text",
            color: "transparent",
            WebkitTextFillColor: "transparent",
            filter: "drop-shadow(0 0 32px rgba(107,71,245,0.85))",
            lineHeight: 1,
          }}
        >
          {counterDisplay}
        </div>
        <div
          style={{
            fontFamily: "Geist, sans-serif",
            fontWeight: 600,
            fontSize: 36,
            color: "#ffffff",
            opacity: 0.9,
            marginTop: 4,
          }}
        >
          mods & plugins
        </div>
        <div
          style={{
            fontFamily: "'Geist Mono', monospace",
            fontWeight: 500,
            fontSize: 22,
            color: "#22d3ee",
            letterSpacing: 1,
            marginTop: 10,
          }}
        >
          14B+ downloads
        </div>
      </div>
    </AbsoluteFill>
  );
}

export const DURATION_POSTER_MODS = 90;

