import { AbsoluteFill, interpolate, Easing, staticFile, useCurrentFrame, useVideoConfig } from "remotion";

const N_LOGOS = 50;
const LOGOS = Array.from({ length: N_LOGOS }, (_, i) => `mods/m${String(i).padStart(2, "0")}.png`);

export default function PosterGridMods() {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const cols = 10;
  const rows = 4;
  const tileSize = 152;
  const gap = 10;
  const gridW = cols * tileSize + (cols - 1) * gap;
  const gridH = rows * tileSize + (rows - 1) * gap;
  const slots = cols * rows; // 40 of the 50 real logos

  const driftX = Math.sin((frame / 100) * Math.PI) * 5;
  const driftY = Math.cos((frame / 100) * Math.PI) * 5;

  const overlayOpacity = interpolate(frame, [34, 54], [0, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });
  const overlayScale = interpolate(frame, [34, 58], [1.12, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });
  const overlayBlur = interpolate(frame, [34, 54], [10, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp",
  });

  const rawCounter = interpolate(frame, [0, 80], [58000, 70000], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.exp),
  });
  const counterValue = Math.round(rawCounter);
  const counterDisplay = counterValue >= 70000 ? "70,000+" : counterValue.toLocaleString();

  const tiles = Array.from({ length: slots });

  return (
    <AbsoluteFill style={{ backgroundColor: "#05060d", fontFamily: "Geist, sans-serif", overflow: "hidden" }}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700;800&family=Geist+Mono:wght@400;500;600&display=swap');`}</style>

      <div
        style={{
          position: "absolute",
          left: (width - gridW) / 2 + driftX,
          top: (height - gridH) / 2 + driftY,
          width: gridW,
          height: gridH,
          display: "grid",
          gridTemplateColumns: `repeat(${cols}, ${tileSize}px)`,
          gridTemplateRows: `repeat(${rows}, ${tileSize}px)`,
          gap,
        }}
      >
        {tiles.map((_, i) => {
          const baseStart = i * 1.7;
          const dur = 12;
          const scale = interpolate(frame, [baseStart, baseStart + dur], [0.85, 1], {
            extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
          });
          const opacity = interpolate(frame, [baseStart, baseStart + dur], [0, 1], {
            extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
          });

          return (
            <div
              key={i}
              style={{
                position: "relative",
                width: tileSize,
                height: tileSize,
                borderRadius: 10,
                border: "1px solid rgba(139,112,251,0.25)",
                background: "linear-gradient(180deg, rgba(30,27,75,0.5) 0%, rgba(13,12,26,0.6) 100%)",
                display: "flex", alignItems: "center", justifyContent: "center",
                overflow: "hidden",
                opacity,
                transform: `scale(${scale})`,
              }}
            >
              <img
                src={staticFile(LOGOS[i % LOGOS.length])}
                style={{ width: "72%", height: "72%", objectFit: "contain", display: "block" }}
              />
            </div>
          );
        })}
      </div>

      <div
        style={{
          position: "absolute", inset: 0,
          background: "radial-gradient(circle at 50% 50%, transparent 26%, rgba(5,6,13,0.55) 66%, rgba(5,6,13,0.85) 100%)",
          pointerEvents: "none",
        }}
      />

      <div
        style={{
          position: "absolute", left: "50%", top: "50%",
          transform: `translate(-50%, -50%) scale(${overlayScale})`,
          opacity: overlayOpacity,
          filter: `blur(${overlayBlur}px)`,
          textAlign: "center",
          display: "flex", flexDirection: "column", alignItems: "center",
          padding: "34px 64px 40px",
          background: "radial-gradient(ellipse at 50% 50%, rgba(5,6,13,0.78) 55%, transparent 100%)",
          borderRadius: 28,
        }}
      >
        <div
          style={{
            fontFamily: "Geist, sans-serif", fontWeight: 700, fontSize: 112, lineHeight: 1,
            background: "linear-gradient(90deg, #3b82f6, #8a70fb, #6f47f5)",
            WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent",
            filter: "drop-shadow(0 0 36px rgba(107,71,245,0.7))",
          }}
        >
          {counterDisplay}
        </div>
        <div style={{ fontFamily: "Geist, sans-serif", fontWeight: 700, fontSize: 38, color: "#ffffff", marginTop: 6 }}>
          mods & plugins
        </div>
        <div
          style={{
            fontFamily: "'Geist Mono', monospace", fontWeight: 500, fontSize: 23, color: "#22d3ee",
            letterSpacing: 2, textTransform: "uppercase", marginTop: 12,
          }}
        >
          14B+ downloads
        </div>
      </div>
    </AbsoluteFill>
  );
}

export const DURATION_POSTER_MODS = 102; // 3.4s @ 30fps

