  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const cols = 8;
  const rows = 5;
  const tileSize = 190;
  const gap = 10;
  const gridW = cols * tileSize + (cols - 1) * gap;
  const gridH = rows * tileSize + (rows - 1) * gap;

  const driftX = Math.sin((frame / 90) * Math.PI) * 6;
  const driftY = Math.cos((frame / 90) * Math.PI) * 6;

  const overlayOpacity = interpolate(frame, [30, 48], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const overlayScale = interpolate(frame, [30, 48], [0.92, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const rawCounter = interpolate(frame, [0, 75], [60000, 70000], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.exp),
  });
  const counterValue = Math.round(rawCounter);
  const counterDisplay =
    counterValue >= 70000 ? "70,000+" : counterValue.toLocaleString();

  const tiles = Array.from({ length: cols * rows });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "#05060d",
        fontFamily: "Geist, sans-serif",
        overflow: "hidden",
      }}
    >
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700;800&family=Geist+Mono:wght@400;500;600&display=swap');`}</style>

      <div
        style={{
          position: "absolute",
          left: (width - gridW) / 2 + driftX,
          top: (height - gridH) / 2 + driftY,
          width: gridW,
          height: gridH,
          display: "grid",
          gridTemplateColumns: `repeat(${cols}, ${tileSize}px)`,
          gridTemplateRows: `repeat(${rows}, ${tileSize}px)`,
          gap,
        }}
      >
        {tiles.map((_, i) => {
          const baseStart = i * 2.5;
          const dur = 12;
          const scale = interpolate(frame, [baseStart, baseStart + dur], [0.85, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });
          const opacity = interpolate(frame, [baseStart, baseStart + dur], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });

          const baseColor = tileColors_muidukf6[i % tileColors_muidukf6.length];
          const icon = tileIcons_muidukf6[i % tileIcons_muidukf6.length];
          const label = `mod-${String(i + 1).padStart(3, "0")}`;

          return (
            <div
              key={i}
              style={{
                position: "relative",
                width: tileSize,
