          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%) scale(${overlayScale})`,
          opacity: overlayOpacity,
          textAlign: "center",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          padding: "32px 60px 36px",
          background: "radial-gradient(ellipse at 50% 50%, rgba(5,6,13,0.72) 60%, transparent 100%)",
