import { interpolate, Easing, useCurrentFrame } from "remotion";

export type CursorKeyframe = { frame: number; x: number; y: number };
export type ClickEvent = { frame: number; x: number; y: number };

function posAt(frame: number, kfs: CursorKeyframe[]): { x: number; y: number } {
  if (frame <= kfs[0].frame) return { x: kfs[0].x, y: kfs[0].y };
  const last = kfs[kfs.length - 1];
  if (frame >= last.frame) return { x: last.x, y: last.y };
  for (let i = 0; i < kfs.length - 1; i++) {
    const a = kfs[i];
    const b = kfs[i + 1];
    if (frame >= a.frame && frame <= b.frame) {
      const x = interpolate(frame, [a.frame, b.frame], [a.x, b.x], {
        easing: Easing.inOut(Easing.cubic),
      });
      const y = interpolate(frame, [a.frame, b.frame], [a.y, b.y], {
        easing: Easing.inOut(Easing.cubic),
      });
      return { x, y };
    }
  }
  return { x: last.x, y: last.y };
}

/** A synthetic mouse cursor driven by keyframes, with a click ripple at
 * specified frames. Keyframes/clicks are in the SEQUENCE-LOCAL frame space
 * (i.e. whatever useCurrentFrame() returns inside the enclosing
 * <Sequence>), not the global timeline. */
export function Cursor({
  keyframes,
  clicks = [],
  visibleFrom = 0,
  visibleUntil,
}: {
  keyframes: CursorKeyframe[];
  clicks?: number[];
  visibleFrom?: number;
  visibleUntil?: number;
}) {
  const frame = useCurrentFrame();
  const { x, y } = posAt(frame, keyframes);

  const fadeIn = interpolate(frame, [visibleFrom, visibleFrom + 8], [0, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp",
  });
  const fadeOut = visibleUntil
    ? interpolate(frame, [visibleUntil - 8, visibleUntil], [1, 0], {
        extrapolateLeft: "clamp", extrapolateRight: "clamp",
      })
    : 1;
  const opacity = Math.min(fadeIn, fadeOut);

  // click scale-pulse: brief press-down (0.9) then a ring that expands out
  let pressScale = 1;
  let ringScale = 0;
  let ringOpacity = 0;
  for (const c of clicks) {
    const dt = frame - c;
    if (dt >= -3 && dt <= 18) {
      const press = interpolate(dt, [-3, 0, 6], [1, 0.82, 1], {
        extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
      });
      pressScale = Math.min(pressScale, press);
    }
    if (dt >= 0 && dt <= 20) {
      ringScale = Math.max(ringScale, interpolate(dt, [0, 20], [0.2, 2.2], {
        extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
      }));
      ringOpacity = Math.max(ringOpacity, interpolate(dt, [0, 20], [0.7, 0], {
        extrapolateLeft: "clamp", extrapolateRight: "clamp",
      }));
    }
  }

  if (opacity <= 0) return null;

  return (
    <div style={{ position: "absolute", left: x, top: y, zIndex: 999, opacity, pointerEvents: "none" }}>
      <div style={{
        position: "absolute", left: -22, top: -22, width: 44, height: 44, borderRadius: "50%",
        border: "2px solid rgba(138,112,251,0.9)",
        transform: `scale(${ringScale})`, opacity: ringOpacity,
      }} />
      <svg width="30" height="38" viewBox="0 0 30 38" style={{
        transform: `scale(${pressScale})`, transformOrigin: "3px 2px",
        filter: "drop-shadow(0 2px 6px rgba(0,0,0,0.6))",
      }}>
        <path d="M2 2 L2 30 L9.5 23.5 L14.5 34.5 L19 32.5 L14 21.5 L24 21.5 Z"
          fill="#ffffff" stroke="#05060d" strokeWidth="1.6" strokeLinejoin="round" />
      </svg>
    </div>
  );
}

