input.content:
import { Img, staticFile } from "remotion";
import { C, NAV_SECTIONS } from "./tokens";

function NavIcon({ active }: { active: boolean }) {
  return (
    <span style={{
      width: 7, height: 7, borderRadius: 2,
      background: active ? C.gradient : "transparent",
      display: "inline-block",
    }} />
  );
}

export function AppShell({ active, children }: { active: string; children: React.ReactNode }) {
  return (
    <div style={{
      position: "absolute", inset: 0, background: C.bg, fontFamily: "Geist, sans-serif",
      display: "flex", flexDirection: "column", overflow: "hidden",
    }}>
      {/* top bar */}
      <div style={{
        height: 68, flexShrink: 0, display: "flex", alignItems: "center",
        borderBottom: `1px solid ${C.panelBorder}`, padding: "0 28px", gap: 24,
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, width: 170 }}>
          <Img src={staticFile("nxeon-logo.png")} style={{ height: 22 }} />
        </div>
        <div style={{
          flex: 1, maxWidth: 640, height: 38, borderRadius: 10, background: "rgba(255,255,255,0.03)",
          border: `1px solid ${C.panelBorder}`, display: "flex", alignItems: "center",
          padding: "0 14px", color: C.textDim, fontSize: 15, fontFamily: "Geist, sans-serif",
        }}>
          Search anything...
        </div>
        <div style={{ flex: 1 }} />
        <div style={{
          padding: "8px 16px", borderRadius: 999, background: "rgba(138,112,251,0.10)",
          border: `1px solid ${C.panelBorderStrong}`, color: C.lightPurple, fontSize: 13, fontWeight: 600,
        }}>
          Refer & earn
        </div>
        <div style={{
          width: 34, height: 34, borderRadius: "50%", background: C.gradient,
          display: "flex", alignItems: "center", justifyContent: "center",
          fontSize: 13, fontWeight: 700, color: "white",
        }}>
          D
        </div>
      </div>

      <div style={{ flex: 1, display: "flex", minHeight: 0 }}>
        {/* sidebar */}
        <div style={{
          width: 190, flexShrink: 0, borderRight: `1px solid ${C.panelBorder}`,
          padding: "22px 14px", display: "flex", flexDirection: "column", gap: 20,
        }}>
          {NAV_SECTIONS.map((sec) => (
            <div key={sec.label}>
              <div style={{
                fontSize: 10, fontWeight: 600, letterSpacing: 1.2, color: C.sectionLabel,
                marginBottom: 8, paddingLeft: 8,
              }}>
                {sec.label}
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                {sec.items.map((item) => {
                  const isActive = item === active;
                  return (
                    <div key={item} style={{
                      display: "flex", alignItems: "center", gap: 9,
                      padding: "8px 8px", borderRadius: 8,
                      background: isActive ? "rgba(138,112,251,0.10)" : "transparent",
                      color: isActive ? C.white : "rgba(255,255,255,0.5)",
                      fontSize: 13.5, fontWeight: isActive ? 600 : 500,
                    }}>
                      <NavIcon active={isActive} />
                      {item}
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>

        {/* content */}
        <div style={{ flex: 1, minWidth: 0, position: "relative", overflow: "hidden" }}>
          {children}
        </div>
      </div>
    </div>
  );
}

