      boxShadow: "0 8px 24px rgba(111,71,245,0.35)",
      ...style,
    }}>
      {children}
    </div>
  );
}

export function Pill({ children, tone = "muted", style }: {
  children: React.ReactNode; tone?: "muted" | "active" | "mint" | "cyan"; style?: React.CSSProperties;
}) {
  const toneMap = {
    muted: { bg: "rgba(255,255,255,0.04)", border: C.panelBorder, color: "rgba(255,255,255,0.6)" },
    active: { bg: "rgba(255,255,255,0.94)", border: "transparent", color: "#0a0e19" },
    mint: { bg: "rgba(17,200,142,0.12)", border: "rgba(17,200,142,0.35)", color: C.mint },
    cyan: { bg: "rgba(34,211,238,0.12)", border: "rgba(34,211,238,0.35)", color: C.cyan },
  }[tone];
  return (
    <div style={{
      display: "inline-flex", alignItems: "center", gap: 6, padding: "5px 12px", borderRadius: 999,
      background: toneMap.bg, border: `1px solid ${toneMap.border}`, color: toneMap.color,
      fontSize: 12.5, fontWeight: 600, ...style,
    }}>
      {children}
    </div>
  );
}

export function StatDot({ color }: { color: string }) {
  return <span style={{
    width: 7, height: 7, borderRadius: "50%", background: color, display: "inline-block",
    boxShadow: `0 0 8px ${color}`,
  }} />;
}

