import { Img, interpolate, Easing, staticFile, useCurrentFrame } from "remotion";
import { AppShell } from "../ui/AppShell";
import { Card, Pill, StatDot } from "../ui/primitives";
import { Cursor } from "../ui/Cursor";
import { C } from "../ui/tokens";

const STATS = [
  { label: "Total Services", value: "12", sub: "Active services", color: C.blue },
  { label: "Monthly Spend", value: "$96.91", sub: "vs. last month", color: C.lightPurple },
  { label: "Uptime Average", value: "99.98%", sub: "Last 30 days", color: C.mint },
  { label: "Support Tickets", value: "0", sub: "Open tickets", color: C.cyan },
];

const DEPLOY_TILES = [
  { label: "VPS Servers", price: "$8.99/mo" },
  { label: "Game Servers", price: "$2.99/mo", badge: "FIRST MONTH FREE" },
  { label: "Cloud Hosting", price: "$2.99/mo" },
];

function reveal(frame: number, start: number) {
  const op = interpolate(frame, [start, start + 14], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const y = interpolate(frame, [start, start + 14], [14, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });
  return { opacity: op, transform: `translateY(${y}px)` };
}

export default function DashboardScreen() {
  const frame = useCurrentFrame();
  const tileGlow = interpolate(frame, [48, 58, 66], [0, 1, 0.4], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AppShell active="Dashboard">
      <div style={{ padding: "26px 34px", height: "100%", overflow: "hidden" }}>
        <div style={reveal(frame, 0)}>
          <div style={{ fontSize: 15, color: C.textMuted, marginBottom: 2 }}>Good afternoon,</div>
          <div style={{ fontSize: 32, fontWeight: 800, color: C.white }}>Demo</div>
        </div>

        <div style={{ display: "flex", gap: 14, marginTop: 22, ...reveal(frame, 6) }}>
          {STATS.map((s) => (
            <Card key={s.label} style={{ flex: 1, padding: "16px 18px" }}>
              <div style={{ fontSize: 12, color: C.sectionLabel, fontWeight: 600, marginBottom: 8 }}>{s.label}</div>
              <div style={{ fontSize: 26, fontWeight: 800, color: C.white }}>{s.value}</div>
              <div style={{ fontSize: 11.5, color: s.color, marginTop: 4, fontWeight: 600 }}>{s.sub}</div>
            </Card>
          ))}
        </div>

        <div style={{ display: "flex", gap: 18, marginTop: 18 }}>
          <Card style={{ flex: 1.4, padding: 22, ...reveal(frame, 14) }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <div style={{ fontSize: 17, fontWeight: 700, color: C.white }}>Services</div>
              <Pill>View All</Pill>
            </div>
            <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
              <Pill tone="active">All Services</Pill>
              <Pill>VPS</Pill>
              <Pill>Game Servers</Pill>
            </div>
            <div style={{ marginTop: 16, display: "flex", flexDirection: "column", gap: 10 }}>
              {[
                { name: "My server", host: "skyblockhardcore.play.nxeon.cloud", loc: "Falkenstein, DE" },
                { name: "My server", host: "hypixel.play.nxeon.cloud", loc: "Falkenstein, DE" },
              ].map((row, i) => (
                <div key={i} style={{
                  display: "flex", alignItems: "center", justifyContent: "space-between",
                  padding: "12px 14px", borderRadius: 10, background: "rgba(255,255,255,0.02)",
                  border: `1px solid ${C.panelBorder}`,
                }}>
                  <div>
                    <div style={{ fontSize: 14, fontWeight: 600, color: C.white }}>{row.name}</div>
                    <div style={{ fontSize: 11.5, color: C.textDim, fontFamily: "'Geist Mono', monospace" }}>{row.host}</div>
                  </div>
                  <div style={{ fontSize: 12.5, color: C.textMuted }}>{row.loc}</div>
                  <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12.5, color: C.mint, fontWeight: 600 }}>
                    <StatDot color={C.mint} /> Online
                  </div>
                </div>
              ))}
            </div>
          </Card>

          <Card
            id="deploy-card"
            style={{ flex: 1, padding: 22, position: "relative", ...reveal(frame, 22) }}
          >
            <div style={{ fontSize: 17, fontWeight: 700, color: C.white }}>Deploy New Service</div>
            <div style={{ fontSize: 12.5, color: C.textMuted, marginTop: 4 }}>Powerful infrastructure, ready when you are.</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginTop: 16 }}>
              {DEPLOY_TILES.map((t) => {
                const isGame = t.label === "Game Servers";
                return (
                  <div key={t.label} style={{
                    padding: "14px 12px", borderRadius: 12,
                    border: isGame ? `1.5px solid rgba(138,112,251,${0.5 + tileGlow * 0.5})` : `1px solid ${C.panelBorder}`,
                    background: isGame ? `rgba(138,112,251,${0.06 + tileGlow * 0.08})` : "rgba(255,255,255,0.02)",
                    position: "relative",
                  }}>
                    {t.badge && (
                      <div style={{ position: "absolute", top: -9, right: 8 }}>
                        <Pill tone="mint" style={{ fontSize: 9.5, padding: "3px 8px" }}>{t.badge}</Pill>
                      </div>
                    )}
                    <div style={{ fontSize: 13, fontWeight: 700, color: C.white }}>{t.label}</div>
                    <div style={{ fontSize: 11.5, color: C.textMuted, marginTop: 3 }}>{t.price}</div>
                  </div>
                );
              })}
            </div>
          </Card>
        </div>
      </div>

      <Cursor
        keyframes={[
          { frame: 8, x: 860, y: 520 },
          { frame: 46, x: 1480, y: 320 },
          { frame: 58, x: 1500, y: 300 },
        ]}
        clicks={[58]}
      />
    </AppShell>
  );
}

export const DURATION_DASHBOARD = 84;

