import { C } from "./tokens";

const STEPS = ["Service", "Game", "Server", "Region", "Payment", "Deploy"];

export function WizardSteps({ current }: { current: number }) {
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 0, marginBottom: 6 }}>
      {STEPS.map((s, i) => {
        const n = i + 1;
        const done = n < current;
        const active = n === current;
        return (
          <div key={s} style={{ display: "flex", alignItems: "center" }}>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
              <div style={{
                width: 30, height: 30, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center",
                fontSize: 12.5, fontWeight: 700,
                background: active ? C.gradient : done ? "rgba(17,200,142,0.18)" : "rgba(255,255,255,0.04)",
                border: active ? "none" : `1px solid ${done ? "rgba(17,200,142,0.5)" : C.panelBorder}`,
                color: active ? "white" : done ? C.mint : C.textDim,
              }}>
                {done ? "✓" : n}
              </div>
              <div style={{ fontSize: 10.5, color: active ? C.white : C.textDim, fontWeight: active ? 700 : 500 }}>{s}</div>
            </div>
            {i < STEPS.length - 1 && (
              <div style={{ width: 46, height: 1.5, background: done ? "rgba(17,200,142,0.4)" : C.panelBorder, margin: "0 4px 18px" }} />
            )}
          </div>
        );
      })}
    </div>
  );
}

export function WizardHeader({ icon, title, current }: { icon: string; title: string; current: number }) {
  return (
    <div>
      <WizardSteps current={current} />
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginTop: 18, justifyContent: "center" }}>
        <span style={{ fontSize: 22 }}>{icon}</span>
        <span style={{ fontSize: 24, fontWeight: 800, color: C.white }}>{title}</span>
      </div>
    </div>
  );
}

