import { interpolate, Easing, staticFile, useCurrentFrame } from "remotion";
import { AppShell } from "../ui/AppShell";
import { WizardHeader } from "../ui/WizardSteps";
import { Cursor } from "../ui/Cursor";
import { C } from "../ui/tokens";

const N = 24;
const COVERS = Array.from({ length: N }, (_, i) => `games/g${String(i).padStart(2, "0")}.jpg`);
const MC_INDEX = 15; // minecraft cover.jpg lands here in the converted set -- selected tile

export default function ChooseGameScreen() {
  const frame = useCurrentFrame();
  const cols = 8;

  const headerOp = interpolate(frame, [0, 12], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const selectOp = interpolate(frame, [50, 58], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AppShell active="Deploy">
      <div style={{ padding: "22px 34px", height: "100%", overflow: "hidden" }}>
        <div style={{ opacity: headerOp }}>
          <WizardHeader icon="🎮" title="Choose your game" current={2} />
        </div>

        <div style={{
          display: "grid", gridTemplateColumns: `repeat(${cols}, 1fr)`, gap: 10,
          marginTop: 22, maxWidth: 1180, marginLeft: "auto", marginRight: "auto",
        }}>
          {COVERS.map((src, i) => {
            const start = i * 1.2;
            const op = interpolate(frame, [start, start + 10], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
            const sc = interpolate(frame, [start, start + 10], [0.9, 1], {
              extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
            });
            const isSelected = i === MC_INDEX;
            return (
              <div key={i} style={{
                position: "relative", aspectRatio: "3/4", borderRadius: 10, overflow: "hidden",
                opacity: op, transform: `scale(${sc})`,
                border: isSelected ? `2.5px solid rgba(138,112,251,${selectOp})` : "1px solid rgba(139,112,251,0.2)",
                boxShadow: isSelected ? `0 0 ${20 * selectOp}px rgba(111,71,245,${0.6 * selectOp})` : "none",
              }}>
                <img src={staticFile(src)} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
                {isSelected && (
                  <div style={{
                    position: "absolute", inset: 0, background: `rgba(111,71,245,${0.18 * selectOp})`,
                  }} />
                )}
              </div>
            );
          })}
        </div>
      </div>

      <Cursor
        keyframes={[
          { frame: 6, x: 900, y: 250 },
          { frame: 40, x: 640, y: 490 },
          { frame: 50, x: 640, y: 490 },
        ]}
        clicks={[50]}
      />
    </AppShell>
  );
}

export const DURATION_CHOOSE_GAME = 78;

