import { interpolate, Easing, useCurrentFrame } from "remotion";
import { AppShell } from "../ui/AppShell";
import { WizardHeader } from "../ui/WizardSteps";
import { Card, GradButton } from "../ui/primitives";
import { Cursor } from "../ui/Cursor";
import { C } from "../ui/tokens";

const PLANS = [
  { ram: "4 GB", slots: "20 slots", price: "$4.99" },
  { ram: "8 GB", slots: "40 slots", price: "$8.99" },
  { ram: "16 GB", slots: "80 slots", price: "$15.99" },
];
const SELECTED = 1;

export default function SizeServerScreen() {
  const frame = useCurrentFrame();
  const headerOp = interpolate(frame, [0, 12], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const selectAt = 36;
  const selGlow = interpolate(frame, [selectAt, selectAt + 8], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const btnPress = interpolate(frame, [58, 62, 66], [1, 0.94, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AppShell active="Deploy">
      <div style={{ padding: "22px 34px", height: "100%", overflow: "hidden", display: "flex", flexDirection: "column", alignItems: "center" }}>
        <div style={{ opacity: headerOp }}>
          <WizardHeader icon="📦" title="Size your server" current={3} />
        </div>

        <div style={{ display: "flex", gap: 20, marginTop: 34 }}>
          {PLANS.map((p, i) => {
            const start = 8 + i * 6;
            const op = interpolate(frame, [start, start + 12], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
            const y = interpolate(frame, [start, start + 12], [16, 0], {
              extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
            });
            const isSel = i === SELECTED;
            const glow = isSel ? selGlow : 0;
            return (
              <Card key={p.ram} style={{
                width: 220, padding: 22, opacity: op, transform: `translateY(${y}px)`,
                border: `1.5px solid rgba(138,112,251,${0.16 + glow * 0.6})`,
                background: `rgba(138,112,251,${0.03 + glow * 0.08})`,
                boxShadow: glow > 0.3 ? `0 0 ${28 * glow}px rgba(111,71,245,${0.45 * glow})` : "none",
              }}>
                <div style={{ fontSize: 15, fontWeight: 700, color: C.white }}>Minecraft — {p.ram}</div>
                <div style={{ fontSize: 12.5, color: C.textMuted, marginTop: 2 }}>{p.slots}</div>
                <div style={{ fontSize: 30, fontWeight: 800, color: C.white, marginTop: 16 }}>
                  {p.price}<span style={{ fontSize: 14, color: C.textDim, fontWeight: 500 }}>/mo</span>
                </div>
                <div style={{ marginTop: 14, display: "flex", flexDirection: "column", gap: 6 }}>
                  {["2 vCPU", `${p.ram} RAM`, "30 GB SSD"].map((f) => (
                    <div key={f} style={{ fontSize: 12, color: C.textMuted, display: "flex", alignItems: "center", gap: 6 }}>
                      <span style={{ color: C.mint }}>✓</span> {f}
                    </div>
                  ))}
                </div>
              </Card>
