import { interpolate, Easing, useCurrentFrame } from "remotion";
import { AppShell } from "../ui/AppShell";
import { WizardHeader } from "../ui/WizardSteps";
import { GradButton } from "../ui/primitives";
import { Cursor } from "../ui/Cursor";
import { C } from "../ui/tokens";

export default function RegionScreen() {
  const frame = useCurrentFrame();
  const headerOp = interpolate(frame, [0, 12], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const globeOp = interpolate(frame, [6, 22], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const rotate = frame * 0.35;

  const selectAt = 42;
  const pinGlow = interpolate(frame, [selectAt, selectAt + 8], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const btnOp = interpolate(frame, [46, 56], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const btnPress = interpolate(frame, [62, 66, 70], [1, 0.94, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AppShell active="Deploy">
      <div style={{ padding: "22px 34px", height: "100%", overflow: "hidden", display: "flex", flexDirection: "column", alignItems: "center" }}>
        <div style={{ opacity: headerOp }}>
          <WizardHeader icon="🌍" title="Where should it live?" current={4} />
        </div>
        <div style={{ fontSize: 13, color: C.textMuted, marginTop: 6 }}>Closer to your players means lower latency.</div>

        <div style={{ position: "relative", width: 560, height: 560, marginTop: 20, opacity: globeOp }}>
          <div style={{
            position: "absolute", inset: 0, borderRadius: "50%",
            background: "radial-gradient(circle at 35% 30%, rgba(138,112,251,0.35), rgba(59,130,246,0.12) 45%, rgba(5,6,13,0.9) 75%)",
            border: "1px solid rgba(138,112,251,0.4)",
            boxShadow: "0 0 80px rgba(111,71,245,0.25), inset 0 0 60px rgba(0,0,0,0.5)",
          }} />
          {/* latitude rings */}
          {[0.32, 0.55, 0.78].map((r, i) => (
            <div key={i} style={{
              position: "absolute", left: `${50 - r * 50}%`, top: `${50 - r * 22}%`,
              width: `${r * 100}%`, height: `${r * 44}%`, borderRadius: "50%",
              border: "1px solid rgba(138,112,251,0.18)",
            }} />
          ))}
          {/* meridians via rotating conic mask look */}
          <div style={{
            position: "absolute", inset: 0, borderRadius: "50%", overflow: "hidden",
            transform: `rotate(${rotate}deg)`,
          }}>
            {[0, 45, 90, 135].map((deg) => (
              <div key={deg} style={{
                position: "absolute", left: "50%", top: 0, width: 1, height: "100%",
                background: "rgba(138,112,251,0.14)", transform: `rotate(${deg}deg)`, transformOrigin: "center",
              }} />
            ))}
          </div>

          {/* data center pins */}
          <div style={{
            position: "absolute", left: "38%", top: "42%", width: 14, height: 14, borderRadius: "50%",
            background: C.gradient, boxShadow: `0 0 ${10 + pinGlow * 16}px rgba(111,71,245,${0.6 + pinGlow * 0.4})`,
            transform: `translate(-50%,-50%) scale(${1 + pinGlow * 0.4})`,
          }} />
          <div style={{
            position: "absolute", left: "68%", top: "58%", width: 8, height: 8, borderRadius: "50%",
            background: "rgba(255,255,255,0.5)",
          }} />

          {/* location card */}
          <div style={{
            position: "absolute", left: "6%", top: "68%", padding: "10px 16px", borderRadius: 12,
            background: "rgba(10,14,25,0.9)", border: `1.5px solid rgba(138,112,251,${0.3 + pinGlow * 0.5})`,
            display: "flex", alignItems: "center", gap: 8, opacity: globeOp,
          }}>
            <span style={{ fontSize: 18 }}>🇩🇪</span>
            <div>
              <div style={{ fontSize: 13, fontWeight: 700, color: C.white }}>Falkenstein, DE</div>
              <div style={{ fontSize: 10.5, color: C.textMuted }}>Europe</div>
            </div>
          </div>
          <div style={{
            position: "absolute", right: "0%", top: "80%", padding: "10px 16px", borderRadius: 12,
            background: "rgba(10,14,25,0.9)", border: `1px solid ${C.panelBorder}`,
            display: "flex", alignItems: "center", gap: 8, opacity: globeOp,
          }}>
            <span style={{ fontSize: 18 }}>🇸🇬</span>
            <div>
              <div style={{ fontSize: 13, fontWeight: 700, color: C.white }}>Singapore</div>
              <div style={{ fontSize: 10.5, color: C.textMuted }}>Asia</div>
            </div>
          </div>
        </div>

        <div style={{ marginTop: 14, opacity: btnOp, transform: `scale(${btnPress})` }}>
          <GradButton style={{ padding: "13px 44px", fontSize: 15 }}>Next →</GradButton>
        </div>
      </div>

      <Cursor
        keyframes={[
          { frame: 8, x: 1400, y: 250 },
          { frame: 34, x: 790, y: 690 },
          { frame: 42, x: 790, y: 690 },
          { frame: 56, x: 958, y: 720 },
          { frame: 66, x: 958, y: 720 },
        ]}
        clicks={[42, 66]}
      />
    </AppShell>
  );
}

export const DURATION_REGION = 78;

