import { interpolate, Easing, useCurrentFrame } from "remotion";
import { AppShell } from "../ui/AppShell";
import { Card, Pill, StatDot } from "../ui/primitives";
import { Cursor } from "../ui/Cursor";
import { C } from "../ui/tokens";

const TABS = ["Overview", "Console", "Mods & Plugins", "Players", "Settings"];

function Sparkline({ color, seed }: { color: string; seed: number }) {
  const pts = Array.from({ length: 24 }, (_, i) => {
    const n = Math.sin(i * 0.6 + seed) * 0.3 + Math.sin(i * 0.21 + seed * 2) * 0.2 + 0.5;
    return `${(i / 23) * 100},${(1 - n) * 100}`;
  }).join(" ");
  return (
    <svg viewBox="0 0 100 100" preserveAspectRatio="none" style={{ width: "100%", height: 60 }}>
      <polyline points={pts} fill="none" stroke={color} strokeWidth="2.2" vectorEffect="non-scaling-stroke" />
    </svg>
  );
}

export default function LiveDashboardScreen() {
  const frame = useCurrentFrame();
  const op = interpolate(frame, [0, 14], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const tabClickAt = 46;
  const activeTab = frame < tabClickAt ? 0 : 2;
  const highlightX = interpolate(frame, [tabClickAt, tabClickAt + 10], [0, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });

  return (
    <AppShell active="My Services">
      <div style={{ padding: "22px 34px", height: "100%", overflow: "hidden", opacity: op }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div>
            <div style={{ fontSize: 20, fontWeight: 800, color: C.white, display: "flex", alignItems: "center", gap: 10 }}>
              My server <Pill tone="mint" style={{ fontSize: 11 }}><StatDot color={C.mint} /> Online</Pill>
            </div>
            <div style={{ fontSize: 12, color: C.textMuted, fontFamily: "'Geist Mono', monospace", marginTop: 3 }}>
              skyblockhardcore.play.nxeon.cloud
            </div>
          </div>
          <div style={{ display: "flex", gap: 10 }}>
            <Pill>Restart</Pill>
            <Pill>Stop</Pill>
          </div>
        </div>

        <div style={{ display: "flex", gap: 4, marginTop: 20, borderBottom: `1px solid ${C.panelBorder}`, position: "relative" }}>
          {TABS.map((t, i) => (
            <div key={t} style={{
              padding: "9px 16px", fontSize: 13, fontWeight: i === activeTab ? 700 : 500,
              color: i === activeTab ? C.white : C.textMuted,
              borderBottom: i === activeTab ? `2px solid ${C.lightPurple}` : "2px solid transparent",
            }}>
              {t}
            </div>
          ))}
        </div>

        <div style={{ display: "flex", gap: 16, marginTop: 20 }}>
          <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 16 }}>
            <div style={{ display: "flex", gap: 14 }}>
              <Card style={{ flex: 1, padding: 16 }}>
                <div style={{ fontSize: 11.5, color: C.sectionLabel, fontWeight: 600 }}>PLAYERS ONLINE</div>
                <div style={{ fontSize: 26, fontWeight: 800, color: C.white, marginTop: 6 }}>7 <span style={{ fontSize: 15, color: C.textDim, fontWeight: 500 }}>/ 40</span></div>
              </Card>
              <Card style={{ flex: 1, padding: 16 }}>
                <div style={{ fontSize: 11.5, color: C.sectionLabel, fontWeight: 600 }}>PING</div>
                <div style={{ fontSize: 26, fontWeight: 800, color: C.mint, marginTop: 6 }}>12ms</div>
              </Card>
              <Card style={{ flex: 1, padding: 16 }}>
                <div style={{ fontSize: 11.5, color: C.sectionLabel, fontWeight: 600 }}>MEMORY</div>
                <div style={{ fontSize: 26, fontWeight: 800, color: C.white, marginTop: 6 }}>5.1 <span style={{ fontSize: 15, color: C.textDim, fontWeight: 500 }}>/ 8 GB</span></div>
              </Card>
            </div>
            <Card style={{ padding: 18 }}>
              <div style={{ fontSize: 12.5, color: C.sectionLabel, fontWeight: 600, marginBottom: 4 }}>CPU USAGE</div>
              <Sparkline color={C.blue} seed={1} />
            </Card>
            <Card style={{ padding: 18 }}>
              <div style={{ fontSize: 12.5, color: C.sectionLabel, fontWeight: 600, marginBottom: 4 }}>MEMORY</div>
              <Sparkline color={C.lightPurple} seed={4} />
            </Card>
          </div>
          <Card style={{ width: 240, padding: 18, flexShrink: 0 }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: C.white, marginBottom: 12 }}>Quick actions</div>
            {["Edit server settings", "Manage plugins", "Install mods", "Create a backup"].map((a) => (
              <div key={a} style={{ fontSize: 12.5, color: C.textMuted, padding: "9px 0", borderBottom: `1px solid ${C.panelBorder}` }}>
                {a}
              </div>
            ))}
          </Card>
        </div>
      </div>

      <Cursor
        keyframes={[
          { frame: 8, x: 900, y: 200 },
          { frame: tabClickAt - 6, x: 600, y: 226 },
          { frame: tabClickAt, x: 600, y: 226 },
        ]}
        clicks={[tabClickAt]}
      />
    </AppShell>
  );
}

export const DURATION_LIVE_DASHBOARD = 72;

