import { interpolate, Easing, staticFile, useCurrentFrame } from "remotion";
import { AppShell } from "../ui/AppShell";
import { Card, Pill } from "../ui/primitives";
import { Cursor } from "../ui/Cursor";
import { C } from "../ui/tokens";

const MOD_NAMES = ["Sodium", "Iris Shaders", "Mod Menu", "Lithium", "Fabric API", "Xaero's Minimap", "Jotunn", "EpicLoot", "Krastorio 2", "Helmod"];
const N = 10;
const LOGOS = Array.from({ length: N }, (_, i) => `mods/m${String(i).padStart(2, "0")}.png`);
const INSTALL_INDEX = 1;
const CLICK_AT = 44;

export default function ModsScreen() {
  const frame = useCurrentFrame();
  const headerOp = interpolate(frame, [0, 12], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const counter = Math.round(interpolate(frame, [0, 40], [61000, 70000], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.exp),
  }));
  const counterDisplay = counter >= 70000 ? "70,000+" : counter.toLocaleString();

  const installed = frame >= CLICK_AT;
  const installOp = interpolate(frame, [CLICK_AT, CLICK_AT + 6], [1, 0.6], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AppShell active="My Services">
      <div style={{ padding: "22px 34px", height: "100%", overflow: "hidden" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", opacity: headerOp }}>
          <div>
            <div style={{ fontSize: 20, fontWeight: 800, color: C.white }}>Mods & Plugins</div>
