import { interpolate, Easing, useCurrentFrame } from "remotion";
import { AppShell } from "../ui/AppShell";
import { Card } from "../ui/primitives";
import { Cursor } from "../ui/Cursor";
import { C } from "../ui/tokens";

function Toggle({ on }: { on: boolean }) {
  const x = interpolate(on ? 1 : 0, [0, 1], [2, 18]);
  return (
    <div style={{
      width: 38, height: 21, borderRadius: 999, position: "relative",
      background: on ? C.gradient : "rgba(255,255,255,0.08)", transition: "none",
    }}>
      <div style={{
        position: "absolute", top: 2, left: x, width: 17, height: 17, borderRadius: "50%",
        background: "white", boxShadow: "0 1px 3px rgba(0,0,0,0.4)",
      }} />
    </div>
  );
}

const ROWS = [
  { label: "Hardcore mode", sub: "Permadeath, no respawns", on: false },
  { label: "Allow flight", sub: "Players can fly in survival", on: true, target: true },
  { label: "PvP", sub: "Player vs player combat", on: true },
  { label: "Whitelist", sub: "Only approved players may join", on: false },
];
const CLICK_AT = 34;

export default function ConfigScreen() {
  const frame = useCurrentFrame();
  const op = interpolate(frame, [0, 14], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const flipped = frame >= CLICK_AT + 4;

  return (
    <AppShell active="My Services">
      <div style={{ padding: "22px 34px", height: "100%", overflow: "hidden", opacity: op }}>
        <div style={{ fontSize: 20, fontWeight: 800, color: C.white }}>Game settings</div>
        <div style={{ fontSize: 12.5, color: C.textMuted, marginTop: 3 }}>Changes apply on next restart.</div>

        <Card style={{ marginTop: 20, padding: "6px 22px", maxWidth: 620 }}>
          {ROWS.map((r, i) => {
            const isTarget = r.target;
            const on = isTarget ? flipped : r.on;
            return (
              <div key={r.label} style={{
                display: "flex", alignItems: "center", justifyContent: "space-between",
                padding: "16px 0", borderBottom: i < ROWS.length - 1 ? `1px solid ${C.panelBorder}` : "none",
              }}>
                <div>
                  <div style={{ fontSize: 14, fontWeight: 600, color: C.white }}>{r.label}</div>
                  <div style={{ fontSize: 12, color: C.textMuted, marginTop: 2 }}>{r.sub}</div>
                </div>
                <Toggle on={on} />
              </div>
            );
          })}
        </Card>
      </div>

      <Cursor
        keyframes={[
          { frame: 10, x: 1100, y: 200 },
          { frame: CLICK_AT - 6, x: 1230, y: 310 },
          { frame: CLICK_AT, x: 1230, y: 310 },
        ]}
        clicks={[CLICK_AT]}
      />
    </AppShell>
  );
}

export const DURATION_CONFIG = 60;

