import { AbsoluteFill, Sequence, interpolate, useCurrentFrame } from "remotion";

export type StackItem = {
  Component: React.ComponentType;
  duration: number;
  overlapNext?: number; // crossfade duration shared with the FOLLOWING item
};

function Faded({ children, duration, overlapIn, overlapOut }: {
  children: React.ReactNode; duration: number; overlapIn: number; overlapOut: number;
}) {
  const frame = useCurrentFrame();
  const inOp = overlapIn > 0
    ? interpolate(frame, [0, overlapIn], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })
    : 1;
  const outOp = overlapOut > 0
    ? interpolate(frame, [duration - overlapOut, duration], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })
    : 1;
  return <AbsoluteFill style={{ opacity: Math.min(inOp, outOp) }}>{children}</AbsoluteFill>;
}

/** Sequences a list of full-screen components back to back, crossfading
 * across each `overlapNext` window instead of hard-cutting -- and instead
 * of pre-rendering each to its own clip and stitching with ffmpeg (which
 * chops motion mid-flight at the cut point), everything lives on one
 * Remotion timeline so a scene's own animation can settle before the
 * transition starts. Returns the total timeline length in frames. */
export function buildStack(items: StackItem[]): { node: React.ReactNode; totalFrames: number } {
  let cursor = 0;
  const starts: number[] = [];
  for (const it of items) {
    starts.push(cursor);
    cursor += it.duration - (it.overlapNext ?? 0);
  }
  // last item is not shortened by its own (nonexistent) overlapNext
  const total = starts[starts.length - 1] + items[items.length - 1].duration;

  const node = (
    <>
      {items.map((it, i) => {
        const overlapIn = i > 0 ? items[i - 1].overlapNext ?? 0 : 0;
        const overlapOut = it.overlapNext ?? 0;
        const Comp = it.Component;
        return (
          <Sequence key={i} from={starts[i]} durationInFrames={it.duration}>
            <Faded duration={it.duration} overlapIn={overlapIn} overlapOut={overlapOut}>
              <Comp />
            </Faded>
          </Sequence>
        );
      })}
    </>
  );
  return { node, totalFrames: total };
}

