                      color: isActive ? C.white : "rgba(255,255,255,0.5)",
                      fontSize: 13.5, fontWeight: isActive ? 600 : 500,
                    }}>
                      <NavIcon active={isActive} />
                      {item}
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>

        {/* content */}
        <div style={{ flex: 1, minWidth: 0, position: "relative", overflow: "hidden" }}>
          {children}
        </div>
      </div>
    </div>
  );
}

import { AbsoluteFill, Img, interpolate, Easing, staticFile, useCurrentFrame } from "remotion";

export default function OutroCta() {
  const frame = useCurrentFrame();

  // --- ambient background: two slow-drifting colour orbs + a pulsing core
  // glow behind the logo, instead of one static blob sitting in a lot of
  // dead space.
  const driftA = Math.sin(frame / 70) * 40;
  const driftB = Math.cos(frame / 85) * 40;
  const pulse = 0.55 + 0.25 * Math.sin(frame / 20);

  // --- one diagonal light sheen sweeps across the frame early, like a
  // logo sting -- a classic "premium reveal" cue.
  const sweepX = interpolate(frame, [4, 30], [-700, 2400], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.cubic),
  });
  const sweepOp = interpolate(frame, [4, 12, 26, 30], [0, 0.5, 0.5, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp",
  });

  const logoOp = interpolate(frame, [0, 16], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const logoScale = interpolate(frame, [0, 20], [0.7, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.back(1.4)),
  });
  const ringScale = interpolate(frame, [0, 28], [0.6, 1.35], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });
  const ringOp = interpolate(frame, [0, 14, 28], [0.9, 0.35, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // headline: letter-spacing pulls IN as it fades up -- a more "epic
  // trailer title" reveal than a plain fade.
  const headOp = interpolate(frame, [20, 38], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const headY = interpolate(frame, [20, 38], [22, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });
  const headTrack = interpolate(frame, [20, 42], [14, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });

  const dividerScale = interpolate(frame, [42, 54], [0, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
  });

  const pillsOp = interpolate(frame, [50, 64], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const pill1Y = interpolate(frame, [50, 64], [16, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.back(1.5)),
  });
  const pill2Y = interpolate(frame, [58, 72], [16, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.back(1.5)),
  });
  const pill2Op = interpolate(frame, [58, 72], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "#05060d", overflow: "hidden",
        display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
      }}
    >
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700;800&family=Geist+Mono:wght@400;500;600&display=swap');`}</style>

      {/* ambient orbs */}
      <div style={{
        position: "absolute", left: 260 + driftA, top: 220 + driftB, width: 560, height: 560,
        borderRadius: "50%", background: "radial-gradient(circle, rgba(59,130,246,0.22) 0%, rgba(59,130,246,0) 70%)",
        filter: "blur(6px)",
      }} />
      <div style={{
        position: "absolute", right: 220 - driftA, bottom: 160 - driftB, width: 620, height: 620,
        borderRadius: "50%", background: "radial-gradient(circle, rgba(111,71,245,0.20) 0%, rgba(111,71,245,0) 70%)",
        filter: "blur(6px)",
      }} />
      {/* core glow behind logo */}
      <div style={{
        position: "absolute", left: "50%", top: "33%", width: 900, height: 620,
        transform: "translate(-50%, -50%)",
        background: "radial-gradient(circle, rgba(138,112,251,0.34) 0%, rgba(111,71,245,0) 70%)",
        opacity: pulse,
      }} />

      {/* diagonal sheen sweep */}
      <div style={{
        position: "absolute", top: -200, left: sweepX, width: 260, height: 1500,
        transform: "rotate(18deg)",
        background: "linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.14) 50%, rgba(255,255,255,0) 100%)",
        opacity: sweepOp,
        pointerEvents: "none",
      }} />

      {/* logo + pulsing ring */}
      <div style={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{
          position: "absolute", width: 260, height: 260, borderRadius: "50%",
          border: "1.5px solid rgba(138,112,251,0.6)",
          transform: `scale(${ringScale})`, opacity: ringOp,
        }} />
        <Img
          src={staticFile("nxeon-logo.png")}
          style={{ width: 280, opacity: logoOp, transform: `scale(${logoScale})`, zIndex: 2 }}
        />
      </div>

      <div
        style={{
          opacity: headOp, transform: `translateY(${headY}px)`,
          marginTop: 40, fontFamily: "Geist, sans-serif", fontWeight: 800, fontSize: 66,
          color: "#ffffff", textAlign: "center", zIndex: 2,
          letterSpacing: `${headTrack}px`,
        }}
      >
        Deploy your game server today
      </div>

      <div style={{
        transform: `scaleX(${dividerScale})`, width: 140, height: 2, marginTop: 30, marginBottom: 26,
        background: "linear-gradient(90deg, transparent, rgba(138,112,251,0.7), transparent)",
      }} />

      <div style={{ display: "flex", gap: 18, zIndex: 2 }}>
        <div style={{
          opacity: pillsOp, transform: `translateY(${pill1Y}px)`,
          padding: "14px 30px", borderRadius: 999,
          background: "linear-gradient(90deg, rgba(59,130,246,0.16), rgba(138,112,251,0.16))",
          border: "1px solid rgba(138,112,251,0.4)",
          fontFamily: "'Geist Mono', monospace", fontSize: 24, color: "#ffffff",
        }}>
          <span style={{ color: "#3b82f6", fontWeight: 700 }}>50% off</span> first purchase
        </div>
        <div style={{
          opacity: pill2Op, transform: `translateY(${pill2Y}px)`,
          padding: "14px 30px", borderRadius: 999,
          background: "rgba(17,200,142,0.12)",
          border: "1px solid rgba(17,200,142,0.4)",
          fontFamily: "'Geist Mono', monospace", fontSize: 24, color: "#ffffff",
        }}>
          <span style={{ color: "#11c88e", fontWeight: 700 }}>10% off</span> for life
        </div>
      </div>
    </AbsoluteFill>
  );
}

export const DURATION_OUTRO = 96; // 3.2s @ 30fps

import { interpolate, Easing, useCurrentFrame } from "remotion";
import { AppShell } from "../ui/AppShell";
import { WizardHeader } from "../ui/WizardSteps";
import { Card, GradButton, Pill } from "../ui/primitives";
import { Cursor } from "../ui/Cursor";
import { C } from "../ui/tokens";

const CODE = "CREATORCODE";

export default function PaymentScreen() {
  const frame = useCurrentFrame();
  const headerOp = interpolate(frame, [0, 12], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const formOp = interpolate(frame, [8, 20], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const typeStart = 26;
  const typeDur = 22;
  const charsShown = Math.floor(interpolate(frame, [typeStart, typeStart + typeDur], [0, CODE.length], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp",
  }));
  const appliedAt = typeStart + typeDur + 6;
  const appliedOp = interpolate(frame, [appliedAt, appliedAt + 10], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const appliedScale = interpolate(frame, [appliedAt, appliedAt + 10], [0.85, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.back(1.6)),
  });
  const strikeOp = appliedOp;

  const btnPress = interpolate(frame, [78, 82, 86], [1, 0.94, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AppShell active="Deploy">
      <div style={{ padding: "20px 34px", height: "100%", overflow: "hidden", display: "flex", flexDirection: "column", alignItems: "center" }}>
        <div style={{ opacity: headerOp }}>
          <WizardHeader icon="💳" title="Payment details" current={5} />
        </div>

        <div style={{ display: "flex", gap: 20, marginTop: 20, opacity: formOp }}>
          <Card style={{ width: 400, padding: 22 }}>
            <div style={{ fontSize: 12, color: C.sectionLabel, fontWeight: 600, marginBottom: 10 }}>CARD DETAILS</div>
            <div style={{
              padding: "11px 14px", borderRadius: 8, background: "rgba(255,255,255,0.03)",
              border: `1px solid ${C.panelBorder}`, fontFamily: "'Geist Mono', monospace", fontSize: 13.5, color: C.white,
              display: "flex", justifyContent: "space-between",
            }}>
              <span>4242 4242 4242 4242</span>
              <span style={{ color: C.textDim }}>10/28</span>
            </div>

            <div style={{ fontSize: 12, color: C.sectionLabel, fontWeight: 600, margin: "18px 0 8px" }}>CREATOR PARTNER CODE</div>
            <div style={{
              padding: "11px 14px", borderRadius: 8,
              background: appliedOp > 0.5 ? "rgba(17,200,142,0.08)" : "rgba(255,255,255,0.03)",
              border: `1.5px solid ${appliedOp > 0.5 ? "rgba(17,200,142,0.5)" : C.panelBorder}`,
              fontFamily: "'Geist Mono', monospace", fontSize: 13.5, color: C.white,
              display: "flex", justifyContent: "space-between", alignItems: "center",
            }}>
              <span>
                {CODE.slice(0, charsShown)}
                <span style={{ opacity: frame % 20 < 10 && charsShown < CODE.length ? 1 : 0 }}>|</span>
              </span>
              <span style={{ opacity: appliedOp, color: C.mint, fontWeight: 700, fontSize: 12 }}>✓ Applied</span>
            </div>
          </Card>

          <Card style={{ width: 320, padding: 22 }}>
            <div style={{ fontSize: 12, color: C.sectionLabel, fontWeight: 600, marginBottom: 12 }}>ORDER SUMMARY</div>
            <div style={{ fontSize: 14, fontWeight: 600, color: C.white }}>Minecraft — 8 GB / 40 slots</div>
            <div style={{ fontSize: 11.5, color: C.textMuted, marginTop: 2 }}>Falkenstein, DE</div>

            <div style={{ marginTop: 18, display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
              <span style={{ fontSize: 13, color: C.textMuted }}>Subtotal</span>
              <span style={{
                fontSize: 15, color: strikeOp > 0.3 ? C.textDim : C.white,
                textDecoration: strikeOp > 0.3 ? "line-through" : "none",
              }}>
                $8.99
              </span>
            </div>
            <div style={{
              display: "flex", justifyContent: "space-between", marginTop: 6, opacity: appliedOp,
              transform: `scale(${appliedScale})`, transformOrigin: "right center",
            }}>
              <span style={{ fontSize: 13, color: C.mint }}>Creator code (-50%)</span>
              <span style={{ fontSize: 13, color: C.mint, fontWeight: 700 }}>-$4.50</span>
            </div>

            <div style={{ height: 1, background: C.panelBorder, margin: "14px 0" }} />
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
              <span style={{ fontSize: 14, fontWeight: 700, color: C.white }}>Due today</span>
              <span style={{ fontSize: 24, fontWeight: 800, color: C.white }}>
                {appliedOp > 0.5 ? "$4.49" : "$8.99"}
              </span>
            </div>

            <div style={{ marginTop: 18, transform: `scale(${btnPress})` }}>
              <GradButton style={{ textAlign: "center" }}>Pay & deploy</GradButton>
            </div>
          </Card>
        </div>
      </div>

      <Cursor
        keyframes={[
          { frame: 10, x: 1300, y: 300 },
          { frame: typeStart - 4, x: 900, y: 456 },
          { frame: appliedAt + 20, x: 1590, y: 716 },
          { frame: 82, x: 1590, y: 716 },
        ]}
        clicks={[82]}
      />
    </AppShell>
  );
}

export const DURATION_PAYMENT = 90;

import { interpolate, Easing, staticFile, useCurrentFrame } from "remotion";
import { AppShell } from "../ui/AppShell";
import { WizardHeader } from "../ui/WizardSteps";
import { Cursor } from "../ui/Cursor";
import { C } from "../ui/tokens";

const N = 24;
const COVERS = Array.from({ length: N }, (_, i) => `games/g${String(i).padStart(2, "0")}.jpg`);
const MC_INDEX = 15; // minecraft cover.jpg lands here in the converted set -- selected tile

export default function ChooseGameScreen() {
  const frame = useCurrentFrame();
  const cols = 8;

  const headerOp = interpolate(frame, [0, 12], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const selectOp = interpolate(frame, [50, 58], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AppShell active="Deploy">
      <div style={{ padding: "22px 34px", height: "100%", overflow: "hidden" }}>
        <div style={{ opacity: headerOp }}>
          <WizardHeader icon="🎮" title="Choose your game" current={2} />
        </div>

        <div style={{
          display: "grid", gridTemplateColumns: `repeat(${cols}, 1fr)`, gap: 10,
          marginTop: 22, maxWidth: 1180, marginLeft: "auto", marginRight: "auto",
        }}>
          {COVERS.map((src, i) => {
            const start = i * 1.2;
            const op = interpolate(frame, [start, start + 10], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
            const sc = interpolate(frame, [start, start + 10], [0.9, 1], {
              extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic),
            });
            const isSelected = i === MC_INDEX;
            return (
              <div key={i} style={{
                position: "relative", aspectRatio: "3/4", borderRadius: 10, overflow: "hidden",
                opacity: op, transform: `scale(${sc})`,
                border: isSelected ? `2.5px solid rgba(138,112,251,${selectOp})` : "1px solid rgba(139,112,251,0.2)",
                boxShadow: isSelected ? `0 0 ${20 * selectOp}px rgba(111,71,245,${0.6 * selectOp})` : "none",
              }}>
                <img src={staticFile(src)} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
                {isSelected && (
                  <div style={{
                    position: "absolute", inset: 0, background: `rgba(111,71,245,${0.18 * selectOp})`,
                  }} />
                )}
              </div>
            );
          })}
        </div>
      </div>

      <Cursor
        keyframes={[
          { frame: 6, x: 900, y: 250 },
          { frame: 40, x: 640, y: 490 },
          { frame: 50, x: 640, y: 490 },
        ]}
        clicks={[50]}
      />
    </AppShell>
  );
}

