import { interpolate, Easing, useCurrentFrame } from "remotion";
import { C } from "../ui/tokens";
import { GradButton } from "../ui/primitives";
import { Cursor } from "../ui/Cursor";

const STEPS = ["Allocating resources", "Configuring network", "Starting the machine", "Installing the game"];
const SWITCH_AT = 46; // frame the view flips from checklist to success

export default function DeployProgressScreen() {
  const frame = useCurrentFrame();

  const checklistOp = interpolate(frame, [SWITCH_AT - 4, SWITCH_AT + 4], [1, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp",
  });
  const successOp = interpolate(frame, [SWITCH_AT, SWITCH_AT + 12], [0, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp",
  });
  const checkScale = interpolate(frame, [SWITCH_AT, SWITCH_AT + 14], [0.5, 1], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.back(1.8)),
  });
  const btnPress = interpolate(frame, [64, 68, 72], [1, 0.94, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <div style={{
      position: "absolute", inset: 0, background: C.bg, fontFamily: "Geist, sans-serif",
      display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
    }}>
      <div style={{
        position: "absolute", left: "50%", top: "50%", width: 700, height: 500,
        transform: "translate(-50%,-50%)",
        background: "radial-gradient(circle, rgba(111,71,245,0.20) 0%, rgba(111,71,245,0) 70%)",
      }} />

      {checklistOp > 0 && (
        <div style={{ opacity: checklistOp, textAlign: "center" }}>
          <div style={{ fontSize: 22, fontWeight: 800, color: C.white, marginBottom: 26 }}>Building your server</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 12, width: 420 }}>
            {STEPS.map((s, i) => {
              const doneAt = 8 + i * 10;
              const done = frame >= doneAt;
              const op = interpolate(frame, [i * 4, i * 4 + 8], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
              return (
                <div key={s} style={{
                  display: "flex", alignItems: "center", justifyContent: "space-between",
                  padding: "12px 16px", borderRadius: 10, background: "rgba(255,255,255,0.02)",
                  border: `1px solid ${done ? "rgba(17,200,142,0.4)" : C.panelBorder}`, opacity: op,
                }}>
                  <span style={{ fontSize: 14, color: done ? C.white : C.textMuted, fontWeight: done ? 600 : 500 }}>{s}</span>
                  <span style={{
                    width: 20, height: 20, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center",
                    background: done ? C.mint : "rgba(255,255,255,0.06)", color: done ? "#05060d" : "transparent",
                    fontSize: 12, fontWeight: 800,
                  }}>
                    ✓
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {successOp > 0 && (
        <div style={{ opacity: successOp, textAlign: "center", position: "absolute" }}>
          <div style={{
            width: 84, height: 84, borderRadius: "50%", margin: "0 auto 22px",
            background: "rgba(17,200,142,0.14)", border: "2px solid rgba(17,200,142,0.6)",
            display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: 40, color: C.mint, transform: `scale(${checkScale})`,
            boxShadow: "0 0 40px rgba(17,200,142,0.35)",
          }}>
            ✓
          </div>
          <div style={{ fontSize: 26, fontWeight: 800, color: C.white }}>Your server is live</div>
          <div style={{ fontSize: 13, color: C.textMuted, marginTop: 8, fontFamily: "'Geist Mono', monospace" }}>
            skyblockhardcore.play.nxeon.cloud
          </div>
          <div style={{ marginTop: 24, transform: `scale(${btnPress})` }}>
            <GradButton style={{ padding: "13px 34px" }}>Open the panel →</GradButton>
          </div>
        </div>
      )}

      <Cursor
        keyframes={[{ frame: SWITCH_AT + 16, x: 958, y: 700 }, { frame: 72, x: 958, y: 700 }]}
        clicks={[72]}
        visibleFrom={SWITCH_AT + 16}
      />
    </div>
  );
}

export const DURATION_DEPLOY_PROGRESS = 78;

